function legacy_applyLanguage(){const lang=prefs.language||'en',dict=localeDictionaries[lang];document.documentElement.lang=lang==='mr'?'mr':lang==='hi'?'hi':'en';if(!dict)return;const walker=document.createTreeWalker($('#app'),NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){const key=node.nodeValue.trim();if(dict[key])node.nodeValue=node.nodeValue.replace(key,dict[key])}}
function hydrateMemory(){state={...FW.defaults,...read('fw-context',{})};const plans=read('fw-plans',[]),checks=read('fw-tasks',[]),ledger=read('fw-bills',[]);saved=Array.isArray(plans)?plans:[];tasks=Array.isArray(checks)?checks:[];bills=Array.isArray(ledger)?ledger:[];fieldLog=read('fw-field-log',[]);if(!Array.isArray(fieldLog))fieldLog=[];actionStates=read('fw-action-status',{});if(!actionStates||typeof actionStates!=='object'||Array.isArray(actionStates))actionStates={};subscription={farmers:500,fee:300,service:180,fixed:50000,...read('fw-subscription',{})};plan=FW.optimize(state)}
function queueServerWrite(key,value){pendingServerWrites.set(key,value);if(!backendHydrated||serverWriteActive)return;serverWriteActive=true;(async()=>{while(backendHydrated&&pendingServerWrites.size){const [recordKey,record]=pendingServerWrites.entries().next().value;pendingServerWrites.delete(recordKey);syncStatus('Saving…');const response=await fetch('/api/records',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({key:recordKey,value:record}),cache:'no-store'});if(!response.ok){pendingServerWrites.set(recordKey,read(recordKey,null));backendHydrated=false;syncStatus('Device only · sign in to sync',true);break}if(!pendingServerWrites.has(recordKey))dirtyKeys.delete(recordKey)}if(backendHydrated&&!pendingServerWrites.size)syncStatus('Cloud synced')})().catch(()=>{backendHydrated=false;syncStatus('Local cache',true)}).finally(()=>{serverWriteActive=false})}
async function syncBackend(){syncStatus('Checking account…',true);try{const sessionResponse=await fetch('/api/session',{headers:{accept:'application/json'},cache:'no-store'});if(sessionResponse.status===401){canManage=false;accessChecked=true;backendHydrated=false;render();syncStatus('Device only · sign in to sync',true);return}if(!sessionResponse.ok)throw new Error('Session check unavailable');const session=await sessionResponse.json();canManage=session.role==='operator';accessChecked=true;const response=await fetch('/api/records',{headers:{accept:'application/json'},cache:'no-store'});if(response.status===401){backendHydrated=false;syncStatus('Device only · sign in to sync',true);render();return}if(!response.ok)throw new Error('Backend unavailable');const data=await response.json(),records=data.records&&typeof data.records==='object'?data.records:{};for(const key of persistedKeys){if(dirtyKeys.has(key)){pendingServerWrites.set(key,read(key,null));continue}if(Object.prototype.hasOwnProperty.call(records,key)){localStorage.setItem(key,JSON.stringify(records[key]))}else{dirtyKeys.add(key);pendingServerWrites.set(key,read(key,key==='fw-context'?FW.defaults:key==='fw-plans'||key==='fw-tasks'||key==='fw-bills'||key==='fw-field-log'?[]:key==='fw-action-status'?{}:{farmers:500,fee:300,service:180,fixed:50000}))}}hydrateMemory();backendHydrated=true;render();syncStatus('Cloud synced');for(const key of dirtyKeys)queueServerWrite(key,read(key,null))}catch{backendHydrated=false;if(!accessChecked){canManage=false;accessChecked=true}syncStatus(typeof navigator!=='undefined'&&!navigator.onLine?'Offline · this device':'Local only · cloud unavailable',true);if(route==='operator')render()}}
function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v));dirtyKeys.add(k);queueServerWrite(k,v);return true}catch{toast('Browser storage is unavailable; this change was not saved.');return false}}
function toast(t){$('#toast').textContent=translateUI(t);$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function head(title,sub,actions=''){if(title==='Your farm, one clear next step at a time.'){title='Overview';sub='Today’s priorities and season outlook.'}return`<div class="heading"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div><div class="buttons">${actions}</div></div>`}
function button(text,act,primary=false,ic='arrow'){return`<button class="btn ${primary?'primary':''}" data-act="${act}">${icon(ic,14)} ${text}</button>`}
function stat(label,value,unit,note,ic='chart'){return`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ic,16)}</span></div><div class="stat-value">${value}<em>${unit}</em></div><div class="stat-note">${note}</div></div>`}
function panel(title,sub,body,link=''){return`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link}</div>${body}</section>`}
function noPlan(){return`<div class="panel empty">${icon('shield',35)}<h2 style="margin-top:16px">Your constraints need a second look.</h2><p>No full-area crop mix meets this budget and water allowance.<br>Try a smaller cultivated area or update the available resources.</p>${button('Edit farm constraints','edit',true,'settings')}</div>`}
function fieldDiagram(p=plan.best){return `<div class="parcel-diagram" role="img" aria-label="Schematic crop allocation, not satellite imagery"><div class="parcel-heading"><span>FIELD PLAN / DEMO</span><span>${formatArea(state.area)}</span></div><div class="parcel-grid">${FW.crops.map((c,i)=>`<div class="parcel-card" style="--parcel:${c.color}"><span>${String(i+1).padStart(2,'0')}</span><strong>${c.name}</strong><small>${formatArea(p?.a?.[i]||0)}</small></div>`).join('')}</div><div class="parcel-caption">Illustrative crop allocation · not a satellite map</div></div>`}
function allocation(p){let start=0;const grad=FW.crops.map((c,i)=>{let prev=start;start+=p.a[i]/state.area*100;return`${c.color} ${prev}% ${start}%`}).join(',');return`<div class="allocation"><div class="donut" style="background:conic-gradient(${grad})"><div class="donut-center"><strong>${(state.areaUnit==='acre'?state.area*areaFactor:state.area).toFixed(2)}</strong><span>${areaUnitName()} planned</span></div></div><div>${FW.crops.map((c,i)=>`<div class="crop-row"><span><i class="crop-dot" style="background:${c.color}"></i>${c.name}<br><small style="margin-left:15px">${i===0?'Pulse · lower water':i===1?'Cereal · stable demand':'Vegetable · higher volatility'}</small></span><span>${formatArea(p.a[i])}</span></div>`).join('')}</div></div><div class="allocation-footer"><span>${icon('shield',13)} ${plan.count} feasible crop mixes</span><span>Risk preference: ${state.risk}/100</span></div>`}
function chart(p){const vals=[0,.14,.33,.51,.66,.81,1],low=p.p10,high=p.p90,mean=p.mean,max=Math.max(high,1);const points=v=>vals.map((x,i)=>`${40+i*70},${157-v*x/max*125}`).join(' ');return`<svg class="chart" viewBox="0 0 490 190" role="img" aria-label="Illustrative cumulative profit range through the season; not a monthly cash flow"><g stroke="#eef0e9" stroke-dasharray="3 4"><path d="M40 25h420M40 70h420M40 115h420M40 157h420"/></g><g fill="#9ca391" font-size="9"><text x="0" y="29">${Math.round(max/1000)}k</text><text x="0" y="75">${Math.round(max/2000)}k</text><text x="10" y="158">0</text></g><polygon points="${points(high)} ${vals.map((x,i)=>`${460-i*70},${157-low*vals[6-i]/max*125}`).join(' ')}" fill="#eaf0dd"/><polyline points="${points(low)}" fill="none" stroke="#b6c593" stroke-dasharray="4 4"/><polyline points="${points(high)}" fill="none" stroke="#c5d3ad"/><polyline points="${points(mean)}" fill="none" stroke="#658452" stroke-width="2.6"/><circle cx="460" cy="${157-mean/max*125}" r="4" fill="#658452"/></svg>`}
function featuredPanel(title,sub,body,link=''){return panel(title,sub,body,link).replace('<section class="panel">','<section class="panel featured-panel">')}
function workspaceBillingWidget(){const due=bills.reduce((n,b)=>n+Math.max(0,Number(b.amount||0)-(b.payments||[]).reduce((x,p)=>x+Number(p.amount||0),0)),0),open=bills.filter(b=>Number(b.amount||0)>(b.payments||[]).reduce((x,p)=>x+Number(p.amount||0),0)),next=open.filter(b=>b.dueDate).sort((a,b)=>a.dueDate.localeCompare(b.dueDate))[0];return `<section class="panel billing-snapshot"><div class="billing-snapshot-copy"><span class="eyebrow">WORKSPACE · BILLING</span><h2>Farm payments at a glance</h2><p>${open.length?`${open.length} bill${open.length===1?'':'s'} open${next?` · next due ${new Date(next.dueDate+'T00:00:00').toLocaleDateString(localeForUI(),{day:'numeric',month:'short'})}`:''}`:'Your bill book is ready when you need it.'}</p></div><div class="billing-snapshot-total"><small>OUTSTANDING</small><strong>${money(due)}</strong></div><a class="btn primary" href="#billing">Open bills ${icon('arrow',13)}</a></section>`}
function resources(){const p=plan.best;return head('Make every resource count.','Financial and irrigation limits flow directly into the crop plan.',button('Adjust constraints','edit',true,'settings'))+(!p?noPlan():`<div class="grid equal">${panel('Water, allocated with intent','Seasonal irrigation allowance · not total crop water demand',FW.crops.map((c,i)=>`<div class="bar-row"><span>${c.name}</span><div class="bar"><span style="width:${p.a[i]*c.water/state.water*100}%;background:${c.color}"></span></div><strong>${num(p.a[i]*c.water)} m³</strong></div>`).join('')+`<div class="result-band"><span>Unallocated buffer</span><strong>${num(state.water-p.water)} <small>m³</small></strong></div>`)}${panel('Capital allocation','Total cultivation cost across the chosen crop mix.',FW.crops.map((c,i)=>`<div class="bar-row"><span>${c.name}</span><div class="bar"><span style="width:${p.a[i]*c.cost/state.budget*100}%;background:${c.color}"></span></div><strong>${money(p.a[i]*c.cost)}</strong></div>`).join('')+`<div class="result-band"><span>Remaining capital</span><strong>${money(state.budget-p.cost)}</strong></div>`)}${panel('Water and budget by crop','Use the seasonal totals to plan field checks; these are model inputs, not measured irrigation prescriptions.',`<div class="table-wrap"><table><thead><tr><th>CROP</th><th>AREA</th><th>SEASON WATER</th><th>WATER / HA</th><th>DEMO CYCLE</th><th>YIELD / WATER</th></tr></thead><tbody>${FW.crops.map((c,i)=>`<tr><td><i class="crop-dot" style="background:${c.color}"></i>${c.name}</td><td>${formatArea(p.a[i])}</td><td>${num(p.a[i]*c.water)} m³</td><td>${num(c.water)} m³/ha</td><td>${c.days} days</td><td>${(p.yields[i]*10/Math.max(1,c.water)).toFixed(2)} q / 1,000 m³</td></tr>`).join('')}</tbody></table></div><div class="notice">Total modeled water is seasonal irrigation need. It excludes effective rainfall, soil moisture, irrigation efficiency, crop stage scheduling and local water rights. Check crop stage and soil moisture in the field before irrigating.</div>`)}</div><div class="grid equal">${panel('Resource review checklist','Observations sync to your private account when connected and remain queued in the browser when offline.',actionList())}${panel('An honest sustainability view','What this prototype measures — and what comes next.',`<div class="timeline"><div><small>SDG 2 / ZERO HUNGER</small><h3>Measure production stability</h3><p>Track simulated yield variability and loss exposure. Nutrition and household food security need field data.</p></div><div><small>SDG 8 / DECENT WORK</small><h3>Protect farm-level viability</h3><p>Include input costs and cash needs. Labor conditions are not measured in this prototype.</p></div><div><small>SDG 12 / RESPONSIBLE PRODUCTION</small><h3>Keep water within a hard limit</h3><p>Show allocation and buffer explicitly. Soil carbon and long-term rotation benefits require additional modeling.</p></div></div>`)}</div>`)}
function finance(){const p=plan.best;return head('Know the economics.','Understand returns, working capital and the cost of uncertainty.',button('Download analysis PDF','export',false,'down'))+(!p?noPlan():`<div class="stats">${stat('Expected gross revenue',money(p.mean+p.cost),'','Synthetic yield × synthetic farm-gate price','chart')}${stat('Cultivation costs',money(p.cost),'','Includes assumed labor and inputs','wallet')}${stat('Expected net return',money(p.mean),'',`${Math.round(p.mean/p.cost*100)}% modeled return on cultivation cost`,'leaf')}${stat('Average worst 10%',money(p.tail),'','Tail mean · lower is riskier','shield')}</div><div class="grid">${panel('Seasonal cash position','Illustrative timing · all crop receipts assumed at harvest',`<div class="table-wrap"><table><thead><tr><th>STAGE</th><th>OUTFLOW</th><th>RECEIPTS</th><th>CASH BALANCE</th></tr></thead><tbody>${['Land preparation','Sowing & inputs','Crop management','Harvest & sale'].map((t,i)=>{const w=[.15,.4,.3,.15],acc=w.slice(0,i+1).reduce((a,b)=>a+b,0);return`<tr><td>${t}</td><td>${money(p.cost*w[i])}</td><td>${i===3?money(p.mean+p.cost):'—'}</td><td>${money(state.budget-p.cost*acc+(i===3?p.mean+p.cost:0))}</td></tr>`}).join('')}</tbody></table></div><div class="notice">Opening cash equals the entered budget. Debt interest, rent, household expenses, taxes and storage costs are excluded.</div>`)}${panel('Break-even lens','Understand the threshold before taking risk.',`<div class="metric-list"><div><span>Minimum gross receipts</span><strong>${money(p.cost)}</strong></div><div><span>Revenue decline to break-even</span><strong>${(100*p.mean/(p.mean+p.cost)).toFixed(1)}%</strong></div><div><span>Modeled loss frequency</span><strong>${p.loss.toFixed(1)}%</strong></div><div><span>Outcome range (P10–P90)</span><strong>${money(p.p10)}–${money(p.p90)}</strong></div></div><a href="#planner" class="btn" style="margin-top:19px">Review the crop plan ${icon('arrow',14)}</a>`)}</div>${panel('Market intelligence, with provenance','Demo prices only. No live quotes or buy/sell signals.',`<div class="table-wrap"><table><thead><tr><th>COMMODITY</th><th>ASSUMED PRICE / Q</th><th>MODELED PRICE NOISE</th><th>SOURCE STATUS</th></tr></thead><tbody>${FW.crops.map(c=>`<tr><td>${c.name}</td><td>${money(c.price)}</td><td>Triangular ±${c.vol*200}%</td><td><span class="badge amber">Synthetic assumption</span></td></tr>`).join('')}</tbody></table></div><div class="notice">Use actual mandi prices net of transport, fees and losses. <a href="https://www.enam.gov.in/web/dashboard/agmarknet" target="_blank" rel="noopener">Open official market dashboard ↗</a></div>`)} `)}
function evidenceDesk(){const e=FW.evidenceAssessment({...state,fieldObservationCount:Math.max(Number(state.fieldObservationCount)||0,fieldLog?.length||0)}),max={profile:20,soil:10,market:30,field:20,weather:20},rows=e.groups.map(g=>'<div class=\"evidence-row\"><div><strong>'+g.label+'</strong><small>'+g.status+'</small></div><strong>'+g.score+' / '+max[g.key]+' pts</strong></div>').join('');return panel('Evidence readiness','A transparent checklist; this score measures input coverage, not recommendation accuracy.','<div class=\"evidence-score\"><strong>'+e.score+'%</strong><span>of available evidence groups represented</span></div><div class=\"evidence-list\">'+rows+'</div><p class=\"tiny\">Farmer-entered soil and market details are unverified. Old prices and forecasts lose readiness points. This score is not a probability that the crop plan will succeed.</p><div class=\"buttons\"><a class=\"btn\" href=\"#profile\">Complete farmer profile</a><a class=\"btn\" href=\"#finance\">Add local prices and costs</a><a class=\"btn\" href=\"#journal\">Log a field observation</a></div>')}
function engineCoverage(){return panel('Challenge module coverage','A straight inventory of what runs in this prototype and what still needs evidence or engineering.',`<div class="table-wrap"><table><thead><tr><th>REQUIRED ENGINE</th><th>STATUS</th><th>IMPLEMENTED TODAY</th><th>MAIN GAP</th></tr></thead><tbody><tr><td>Agricultural data fusion & context</td><td><span class="badge amber">Partial</span></td><td>Farmer-entered land, soil, budget, water, stage and evidence completeness; live forecast in a separate module.</td><td>No verified soil test or sensor data; entered labels and sources remain unverified.</td></tr><tr><td>Probabilistic crop risk & yield</td><td><span class="badge amber">Prototype</span></td><td>240 seeded synthetic yield/price draws per candidate; mean, P10, P90 and lower-tail outcomes.</td><td>No calibration against historical district/season outcomes; no model validation set.</td></tr><tr><td>Multi-objective resource optimizer</td><td><span class="badge">Working demo</span></td><td>Searches 5% crop mixes subject to hard land, budget and water limits; ranks return, downside and water use.</td><td>No labor, rotation, soil health, nutrition or stage-specific irrigation constraints.</td></tr><tr><td>Farm finance & market intelligence</td><td><span class="badge amber">Partial</span></td><td>Crop unit economics, dated farmer-entered prices/costs, bill ledger and payment records.</td><td>No live mandi data, credit, household cash flow or settlement.</td></tr><tr><td>What-if & stress testing</td><td><span class="badge amber">Prototype</span></td><td>Interactive joint rainfall, price, input-cost and water shocks; re-optimizes feasible mixes.</td><td>Synthetic assumptions remain uncalibrated; extreme-event tails and climate-price correlation are not modeled.</td></tr><tr><td>Evidence-grounded decision agents</td><td><span class="badge amber">Guardrails only</span></td><td>Source links, dated farmer-entered observations and explicit limits.</td><td>No retrieval pipeline or autonomous agents; local sources are not automatically verified.</td></tr><tr><td>Adaptive & offline farmer interface</td><td><span class="badge amber">Partial</span></td><td>English, Marathi and Hindi labels; browser cache, queued edits and signed-in sync.</td><td>No field-tested low-bandwidth usability, voice flow or farmer onboarding study.</td></tr><tr><td>Farmer portfolio & viability</td><td><span class="badge amber">Partial</span></td><td>Saved decision history and an owner-only subscription unit-economics worksheet.</td><td>No farmer cohort data, willingness-to-pay evidence, renewals or commercial traction.</td></tr></tbody></table></div><div class="notice amber">This inventory reflects implemented code paths, not an impact claim. The highest-value competition work is local calibration and a held-out pilot, followed by live district market data and farmer usability evaluation.</div>`)}
let stressControls={rain:20,price:15,cost:20,water:70};
function stressLab(){const cases=[{id:'current',label:'Current farm context',patch:{},why:'The entered water, evidence and price assumptions.'},{id:'dry',label:'Dry-season stress',patch:{rain:-20},why:'Yield pressure from a 20-point rainfall shock.'},{id:'market',label:'Lower farm-gate prices',patch:{price:-15},why:'A 15% price decline across the modeled crops.'},{id:'inputs',label:'Input-cost increase',patch:{costShock:20},why:'A 20% cultivation-cost increase.'},{id:'water',label:'Water availability falls',patch:{water:state.water*.7},why:'Only 70% of the entered water remains available.'}];const rows=cases.map(x=>{const result=FW.optimize({...state,...x.patch}),p=result.best;return{...x,result,p}});const base=rows[0].p;return panel('Decision stress test','Re-optimize crop mixes under fixed scenarios and a joint scenario you can adjust.',`<div class="table-wrap"><table><thead><tr><th>SCENARIO</th><th>BEST MIX</th><th>MEAN NET</th><th>LOWER P10</th><th>WATER</th><th>FEASIBLE MIXES</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${x.label}</strong><br><small>${x.why}</small></td><td>${x.p?FW.crops.map((c,i)=>x.p.a[i]>.001?`${c.name} ${formatArea(x.p.a[i])}`:'').filter(Boolean).join(' · ')||'—':'No feasible mix'}</td><td>${x.p?money(x.p.mean):'—'}${x.p&&base?`<small class="${x.p.mean<base.mean?'negative':'positive'}"> ${x.p.mean-base.mean>=0?'+':''}${money(x.p.mean-base.mean)} vs current</small>`:''}</td><td>${x.p?money(x.p.p10):'—'}</td><td>${x.p?num(x.p.water)+' m³':'—'}</td><td>${x.result.count}</td></tr>`).join('')}</tbody></table></div>${customStressPanel()}<div class="notice amber">These are deterministic stress scenarios over synthetic crop assumptions, not probabilities, forecasts or validated outcomes. Compare with local agronomist advice before spending.</div><p class="tiny">Reproducibility: fixed simulation seed 4217 · 240 draws per candidate mix · 5% land-allocation increments.</p>`)}
function customStressPanel(){const sliders=[['rain','Yield pressure',0,40],['price','Price decline',0,40],['cost','Input cost increase',0,50],['water','Water available',40,100]],result=FW.optimize({...state,rain:Number(state.rain||0)-stressControls.rain,price:Number(state.price||0)-stressControls.price,costShock:stressControls.cost,water:state.water*stressControls.water/100});return panel('Build a joint scenario','Move multiple conditions together. The same land, budget and water limits still apply.',`<div class="controls">${sliders.map(([k,label,min,max])=>`<div class="control"><label for="stress-${k}">${label} <output id="stress-${k}-out">${stressControls[k]}%</output></label><input id="stress-${k}" type="range" min="${min}" max="${max}" value="${stressControls[k]}" data-stress="${k}"></div>`).join('')}</div><div id="custom-stress-result">${customStressResult(result)}</div><p class="tiny">Yield pressure is a model assumption, not a rainfall forecast or crop-specific response curve.</p>`)}
function customStressResult(result){const p=result.best;return p?`<div class="overview-metrics"><div class="overview-metric"><span>Mean net</span><strong>${money(p.mean)}</strong></div><div class="overview-metric"><span>Lower P10</span><strong>${money(p.p10)}</strong></div><div class="overview-metric"><span>Feasible mixes</span><strong>${result.count}</strong></div></div><p>Selected mix: ${FW.crops.map((c,i)=>p.a[i]>.001?`${c.name} ${formatArea(p.a[i])}`:'').filter(Boolean).join(' · ')} · ${num(p.water)} m³ water · ${money(p.cost)} cost</p>`:'<div class="notice amber">No feasible crop mix remains under these combined constraints.</div>'}
function validationBench(){const v=FW.validationSuite(state);return panel('Prototype validation bench',`${v.passed} of ${v.total} software checks pass on the current farm inputs.`, `<div class="evidence-list">${v.checks.map(x=>`<div class="evidence-row"><div><strong>${x.label}</strong><small>${x.detail}</small></div><strong class="${x.pass?'positive':'negative'}">${x.pass?'PASS':'CHECK'}</strong></div>`).join('')}</div><div class="metric-list"><div><span>Scenario draws per mix</span><strong>${v.draws} · fixed seed ${v.seed}</strong></div><div><span>Validation scope</span><strong>Synthetic model checks</strong></div></div><div class="notice amber">${v.scope} To raise impact evidence, run a consented, agronomist-reviewed pilot and evaluate on held-out farms and seasons against farmer practice.</div>`)}
function evidence(){const p=plan.best,b=plan.baseline;return head('Trust starts with transparency.','Every result has assumptions. Here is where you can inspect them.',button('Download PDF report','export',false,'down'))+`<div class="grid equal">${panel('A connected decision pipeline','Modular computation, without unnecessary agent orchestration.',`<div class="timeline"><div><small>01 / CONTEXT ENGINE</small><h3>Farm constraints + evidence quality</h3><p>Normalize hectares, rupees and cubic metres. Incomplete evidence widens crop-level yield uncertainty.</p></div><div><small>02 / RISK + OPTIMIZATION</small><h3>Feasible crop mixes → uncertain outcomes</h3><p>Enumerate 5% land increments. Evaluate 240 reproducible draws per mix using shared climate risk and independent price shocks.</p></div><div><small>03 / DECISION + EXPLANATION</small><h3>Rank trade-offs, expose constraints</h3><p>Score = mean profit − risk weight × (mean − worst-decile mean) − a small water-use penalty. No LLM generates numeric estimates.</p></div><div><small>04 / ADAPTATION</small><h3>Update, compare, retain a record</h3><p>Inputs recompute all views. Saved plans preserve assumptions for later review.</p></div></div>`)}${panel('Source library','External references inform the design, not the demo coefficients.',`<div class="source-list"><a href="https://www.fao.org/aquacrop/overview/en" target="_blank" rel="noopener"><span>FAO AquaCrop<br><small>Reference for crop–water modeling</small></span>↗</a><a href="https://www.fao.org/aquacrop/overview/limitations/en/" target="_blank" rel="noopener"><span>AquaCrop limitations<br><small>Calibration and model scope</small></span>↗</a><a href="https://agromet.imd.gov.in/index.php/login/adv_status_index" target="_blank" rel="noopener"><span>IMD Agromet advisories<br><small>Local agricultural weather guidance</small></span>↗</a><a href="https://www.enam.gov.in/web/dashboard/agmarknet" target="_blank" rel="noopener"><span>e-NAM / AGMARKNET<br><small>Official market price reference</small></span>↗</a></div><div class="notice amber">No live data integration is claimed. This app does not implement AquaCrop, diagnose crop disease, or recommend pesticide doses.</div>`)}</div>${panel('Baseline comparison','All-wheat baseline versus the optimized mix, evaluated with identical synthetic scenarios.',!p?'<p>No feasible optimized plan is available.</p>':`<div class="table-wrap"><table><thead><tr><th>MODEL METRIC</th><th>ALL-WHEAT BASELINE</th><th>CURRENT PLAN</th></tr></thead><tbody><tr><td>Expected net return</td><td>${money(b.mean)}</td><td>${money(p.mean)}</td></tr><tr><td>Downside P10</td><td>${money(b.p10)}</td><td>${money(p.p10)}</td></tr><tr><td>Irrigation</td><td>${num(b.water)} m³</td><td>${num(p.water)} m³</td></tr><tr><td>Meets resource constraints</td><td>${b.feasible?'Yes':'No — infeasible baseline'}</td><td>Yes</td></tr></tbody></table></div><div class="notice">These are within-model comparisons, not measured farm impact. ${!b.feasible?'The baseline is infeasible under current constraints; this is not a like-for-like achievable alternative.':''}</div>`)}<div class="grid equal" style="margin-top:22px">${panel('Limits that matter','A prototype must be honest about its boundaries.',`<details open><summary>No field validation yet</summary><p>Crop coefficients and distributions are illustrative. The modeled loss probability is not a calibrated real-world probability. Regional suitability, pests, labor availability and crop rotation need explicit constraints.</p></details><details><summary>What does “uncertainty” mean here?</summary><p>Shared climate variation is the sum of three uniform draws, centered and scaled. Yield has extra crop noise; missing evidence increases it. Price shocks are triangular. This simplified joint distribution excludes climate-price correlation and extreme tails.</p></details><details><summary>Why no autonomous AI agents?</summary><p>The bounded prototype uses deterministic modules for reproducibility. A future evidence agent may retrieve and cite advisories, but should never override numerical constraints or invent missing measurements.</p></details>`)}${panel('Validation & commercial pathway','A credible next step beyond the demo.',`<p class="tiny">Validate with an FPO and an agronomist: collect consented historical farm records, hold out villages and seasons, compare against farmer practice and simple heuristics, and report calibration, net margin, water use and adoption.</p><div class="metric-list"><div><span>Reproducibility</span><strong>Fixed seed 4217</strong></div><div><span>Commercial model</span><strong>FPO-sponsored access</strong></div><div><span>Illustrative annual fee / farmer</span><strong>₹300</strong></div><div><span>Assumed annual service cost</span><strong>₹180</strong></div></div><p class="tiny">₹120 contribution before acquisition and fixed costs. These are business hypotheses, not validated pricing or traction.</p>`)}</div>${validationBench()}${evidenceDesk()}${engineCoverage()}${stressLab()}`}
function portfolio(){return head('Decisions worth keeping.','Saved farm decisions sync to your private account for side-by-side review.',button('Save current plan','save',true,'plus'))+panel('Your decision portfolio',`${saved.length} saved ${saved.length===1?'record':'records'} · account sync with offline cache`,saved.length? saved.map((s,i)=>`<div class="saved-row"><div><h3 data-i18n-ignore>${esc(s.name)}</h3><p>${esc(formatSavedDate(s.date))} · ${formatArea(s.context.area,s.context.areaUnit||'ha')}</p><p>Expected ${money(s.result.mean)} · P10 ${money(s.result.p10)} · ${s.a.map(a=>formatArea(a,s.context.areaUnit||'ha')).join(' / ')} (CP / WH / ON)</p></div><div class="buttons"><button class="btn" data-load="${i}">Open</button><button class="btn" data-delete="${i}" data-i18n-ignore aria-label="${esc(translateUI('Delete ' + s.name))}">${icon('close',13)}</button></div></div>`).join(''):`<div class="empty">${icon('brief',35)}<h2 style="margin-top:15px">Your first saved decision starts here.</h2><p>Save a crop plan so you can compare it later.</p>${button('Save first plan','save',true,'plus')}</div>`)+`<div class="notice">${icon('info',14)} Records sync to your private sign-in and stay cached in this browser for offline use. Download a PDF analysis for a shareable summary; the bill ledger exports separately as CSV. Calculations work without a data connection once the app is loaded; offline reload depends on your browser cache.</div>`}
function billing(){const allPayments=bills.flatMap(b=>(b.payments||[]).map(p=>({...p,billId:b.id,supplier:b.supplier}))).sort((a,b)=>(b.date||'').localeCompare(a.date||''));const paid=bills.reduce((n,b)=>n+(b.payments||[]).reduce((x,p)=>x+Number(p.amount||0),0),0);const due=bills.reduce((n,b)=>n+Math.max(0,Number(b.amount||0)-(b.payments||[]).reduce((x,p)=>x+Number(p.amount||0),0)),0);const fmt=d=>d?new Date(d+'T00:00:00').toLocaleDateString(localeForUI(),{day:'numeric',month:'short',year:'numeric'}):'—';return head('A clear record for every rupee.','Track farm input bills, supplier dues, and payments made.',button('Export ledger','billing-export',false,'down')+button('Add a bill','billing-add',true,'plus'))+`<div class="stats">${stat('Bills outstanding',money(due),'',`${bills.filter(b=>Number(b.amount||0)>(b.payments||[]).reduce((n,p)=>n+Number(p.amount||0),0)).length} open bills`,'clock')}${stat('Paid and recorded',money(paid),'',`${allPayments.length} recorded payments · private account`,'check')}${stat('Bills recorded',bills.length,'',`Input, labor, services and more`,'brief')}${stat('Current plan estimate',money(plan.best?.mean||0),'','Synthetic net return · planning estimate','leaf')}</div><div class="notice amber">${icon('info',14)} Fieldwise stores bill records in your private account and browser cache; it does not send or receive money. Use your bank, UPI app or agreed payment method first, then record the completed payment here. Do not store PINs, OTPs or full account details.</div><div class="grid" style="margin-top:22px">${panel('Supplier bills','Enter a bill when a farm purchase or service is agreed.',bills.length?`<div class="table-wrap"><table><thead><tr><th>BILL / SUPPLIER</th><th>CATEGORY</th><th>DUE DATE</th><th>AMOUNT</th><th>PAID</th><th>REMAINING</th><th>STATUS</th><th></th></tr></thead><tbody>${bills.slice().sort((a,b)=>(a.dueDate||'').localeCompare(b.dueDate||'')).map(b=>{const p=(b.payments||[]).reduce((n,x)=>n+Number(x.amount||0),0),r=Math.max(0,Number(b.amount)-p);return`<tr><td><strong>${esc(b.id)}</strong><br><small data-i18n-ignore>${esc(b.supplier)}</small></td><td>${esc(b.category)}</td><td>${fmt(b.dueDate)}</td><td>${money(b.amount)}</td><td>${money(p)}</td><td>${money(r)}</td><td><span class="badge ${r?'amber':''}">${r===0?'Settled':p?'Part paid':'Due'}</span></td><td>${r?`<button class="btn" data-pay="${esc(b.id)}">Record payment</button>`:'<span class="muted">Complete</span>'}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty">${icon('brief',35)}<h2 style="margin-top:15px">Your bill book starts here.</h2><p>Add a supplier or service bill to track what’s due.<br>Record part payments and export the ledger whenever you need it.</p>${button('Add your first bill','billing-add',true,'plus')}</div>`)}${panel('Payment history','A dated log of payments you have already made.',allPayments.length?`<div class="table-wrap"><table><thead><tr><th>DATE</th><th>SUPPLIER</th><th>BILL</th><th>METHOD</th><th>REFERENCE</th><th>AMOUNT</th></tr></thead><tbody>${allPayments.map(p=>`<tr><td>${fmt(p.date)}</td><td><span data-i18n-ignore>${esc(p.supplier)}</span></td><td>${esc(p.billId)}</td><td>${esc(p.method)}</td><td><span data-i18n-ignore>${esc(p.reference||'—')}</span></td><td>${money(p.amount)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="mini-card"><h3>No payments recorded yet</h3><p>When you pay a bill outside Fieldwise, use “Record payment” to keep a receipt reference here.</p></div>`,'<span class="pill">Account-scoped records</span>')}</div><div class="grid equal">${panel('A manageable bill schedule','Review due dates with your cash plan.',`<div class="metric-list"><div><span>Open balance across bills</span><strong>${money(due)}</strong></div><div><span>Upcoming within 7 days</span><strong>${money(bills.filter(b=>b.dueDate&&new Date(b.dueDate+'T23:59:59')>=new Date()&&new Date(b.dueDate+'T00:00:00')<=new Date(Date.now()+7*86400000)).reduce((sum,b)=>sum+Math.max(0,Number(b.amount)-(b.payments||[]).reduce((n,p)=>n+Number(p.amount||0),0)),0))}</strong></div><div><span>Working capital entered</span><strong>${money(state.budget)}</strong></div><div><span>Crop return estimate</span><strong>${money(plan.best?.mean||0)}</strong></div></div><p class="tiny">Crop return is a synthetic planning estimate; it is not cash on hand. Consider harvest timing, household needs, debt and other expenses.</p>`)}${panel('Records stay with you','No bank details or payment credentials are needed.',`<p class="tiny">Bills and payments sync to your private account and remain cached in this browser for offline access. Export the CSV ledger for spreadsheet use or your own backup. Actual collection or bank settlement still requires a verified provider and merchant account.</p><div class="notice">${icon('shield',14)} Never enter an OTP, UPI PIN, card number, password or full bank account number in a bill note or reference field.</div>`)}</div>`}
function subscriptionMetrics(){const members=Number(subscription.farmers)||0,fee=Number(subscription.fee)||0,service=Number(subscription.service)||0,fixed=Number(subscription.fixed)||0,per=fee-service,gross=members*fee,variable=members*service,contribution=gross-variable,net=contribution-fixed,breakeven=per>0?Math.ceil(fixed/per):null;return `<div class="subscription-metrics"><div><small>ANNUAL GROSS REVENUE</small><strong>${money(gross)}</strong><span>${num(members)} farmers × ${money(fee)}</span></div><div><small>CONTRIBUTION AFTER SERVICE COST</small><strong>${money(contribution)}</strong><span>${money(per)} per farmer before fixed costs</span></div><div class="${net>=0?'positive-card':'negative-card'}"><small>AFTER FIXED COST ASSUMPTION</small><strong>${money(net)}</strong><span>${net>=0?'Illustrative surplus':'Illustrative shortfall'} · before tax/payment fees</span></div></div><div class="metric-list"><div><span>Estimated annual service costs</span><strong>${money(variable)}</strong></div><div><span>Fixed operating cost assumption</span><strong>${money(fixed)}</strong></div><div><span>Subscribers to cover fixed costs</span><strong>${breakeven===null?'Not reachable at this price':num(breakeven)}</strong></div></div>`}
function pdfClean(value){const slash=String.fromCharCode(92);return Array.from(String(value??'').normalize('NFKD')).map(ch=>{if(ch==='₹')return 'INR ';if('–—→·×'.includes(ch))return '-';if(ch==='≥')return '>=';if(ch==='≤')return '<=';if(ch===slash||ch==='('||ch===')')return slash+ch;const n=ch.charCodeAt(0);return n<32||n>126?' ':ch}).join('')}
function downloadAnalysisPdf(){const p=plan.best,day=new Date().toLocaleDateString(localeForUI(),{day:'numeric',month:'long',year:'numeric'}),allocation=p?FW.crops.map((c,i)=>`${c.name}: ${formatArea(p.a[i])} (estimated ${p.yields[i].toFixed(1)} quintals/ha)`).join(' | '):'No crop mix is feasible under current land, budget and water constraints.';const rows=[['title','Farm decision analysis'],['subtitle',`${state.name} | ${state.region} | ${day}`],['section','SEASON PLAN'],['body',`Cultivated area: ${formatArea(state.area)} | Soil label: ${state.soil} (context only)`],['body',`Crop allocation: ${allocation}`],['body',`Water: ${p?num(p.water):0} of ${num(state.water)} cubic metres | Budget used: ${money(p?.cost||0)} of ${money(state.budget)}`],['section','ILLUSTRATIVE FINANCIAL ESTIMATES'],['body',`Expected gross revenue: ${money(p?p.mean+p.cost:0)} | Cultivation cost: ${money(p?.cost||0)} | Expected net: ${money(p?.mean||0)}`],['body',`Downside P10: ${money(p?.p10||0)} | P10-P90 range: ${money(p?.p10||0)} to ${money(p?.p90||0)} | Simulated loss frequency: ${p?p.loss.toFixed(1):0}%`],['body',`Average worst 10% net outcome: ${money(p?.tail||0)} | Estimated break-even gross receipts: ${money(p?.cost||0)}`],['section','HOW THIS ESTIMATE WAS MADE'],['body','Deterministic crop-mix grid search in 5% land increments; hard budget and water limits; 240 reproducible simulations; seed 4217.'],['body','The objective balances mean net return, worst-decile outcomes and a water-use penalty. Crop prices, costs, yields and risk distributions are synthetic demo assumptions.'],['section','LIMITATIONS AND NEXT CHECKS'],['body','Not validated agronomic or financial advice. No live weather, soil test or mandi data is connected. Suitability, debt, rent, household needs, labor, transport, pests and long-term soil effects are not modeled.'],['body','Verify local soil and water conditions, get current quotations and market prices, and review the plan with a qualified local advisor before spending. A simulated probability is not a calibrated real-world probability.'],['foot','Fieldwise | Synthetic demonstration | No imagery included']];const pageLines=[],maxChars=88;for(const [type,text] of rows){for(const para of text.split('\n')){let line='';for(const word of para.split(/\s+/)){if((line+' '+word).trim().length>maxChars&&line){pageLines.push([type,line]);line=word}else line=(line+' '+word).trim()}if(line)pageLines.push([type,line])}}const groups=[];let pg=[],y=748;for(const row of pageLines){const step=row[0]==='section'?23:row[0]==='title'?31:row[0]==='subtitle'?22:15;if(y-step<62){groups.push(pg);pg=[];y=748}pg.push({...{type:row[0],text:row[1],y},step});y-=step}if(pg.length)groups.push(pg);const enc=new TextEncoder(),objects=[];objects[1]='<< /Type /Catalog /Pages 2 0 R >>';objects[3]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';objects[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>';const pageRefs=[];groups.forEach((items,i)=>{const pageId=5+i*2,contentId=pageId+1;pageRefs.push(`${pageId} 0 R`);let stream='q 0.09 0.25 0.20 rg 0 786 595 56 re f Q\n';stream+='BT /F2 10 Tf 1 1 1 rg 44 817 Td (FIELDWISE  |  FARM DECISION SUPPORT) Tj ET\n';for(const r of items){const isSection=r.type==='section',isTitle=r.type==='title',font=isSection||isTitle?'F2':'F1',size=isTitle?20:isSection?10:r.type==='subtitle'?9:r.type==='foot'?8:9,color=isSection?'0.15 0.34 0.25':r.type==='foot'?'0.38 0.42 0.38':'0.12 0.16 0.14';stream+=`BT /${font} ${size} Tf ${color} rg 46 ${r.y} Td (${pdfClean(r.text)}) Tj ET\n`}stream+=`BT /F1 8 Tf 0.42 0.46 0.42 rg 500 28 Td (${i+1} / ${groups.length}) Tj ET\n`;objects[pageId]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${contentId} 0 R >>`;objects[contentId]=`<< /Length ${enc.encode(stream).length} >>\nstream\n${stream}endstream`});objects[2]=`<< /Type /Pages /Kids [${pageRefs.join(' ')}] /Count ${groups.length} >>`;let pdf='%PDF-1.4\n',offsets=[0];for(let i=1;i<objects.length;i++){offsets[i]=enc.encode(pdf).length;pdf+=`${i} 0 obj\n${objects[i]}\nendobj\n`}const xref=enc.encode(pdf).length;pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let i=1;i<objects.length;i++)pdf+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;pdf+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;const blob=new Blob([pdf],{type:'application/pdf'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='fieldwise-farm-analysis.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Farm analysis PDF downloaded.')}
function savePlan(){if(!plan.best){toast('Adjust your constraints before saving a plan.');return}const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>Keep this decision.</h2><button class="close" data-act="close" aria-label="Close">×</button></div><p>Save the assumptions, allocation and simulated outcomes.</p><form id="save-form"><label for="plan-name">Plan name</label><input id="plan-name" name="planName" value="${translateUI('Rabi crop plan')} ${saved.length+1}" maxlength="60" required style="margin-top:9px"><button class="btn primary" type="submit" style="margin-top:20px">Save to portfolio</button></form>`;applyLanguage(d);d.showModal()}
function billForm(){const d=$('#modal'),today=new Date().toISOString().slice(0,10);d.innerHTML=`<div class="modal-head"><h2>Add a farm bill.</h2><button class="close" data-act="close" aria-label="Close">×</button></div><p>Enter a supplier bill, service fee or farm purchase due.</p><form id="bill-form"><div class="form-grid"><div class="full"><label for="supplier">Supplier or service provider</label><input id="supplier" name="supplier" required maxlength="80" placeholder="e.g. local seed shop"></div><div><label for="category">Bill category</label><select id="category" name="category">${['Seeds & planting','Fertilizer & soil','Labor','Irrigation & water','Equipment','Transport','Other'].map(x=>`<option value="${esc(x)}">${x}</option>`).join('')}</select></div><div><label for="amount">Bill amount (₹)</label><input id="amount" name="amount" type="number" min="1" max="10000000" step="1" required placeholder="0"></div><div><label for="dueDate">Due date</label><input id="dueDate" name="dueDate" type="date" value="${today}" required></div></div><div class="buttons" style="margin-top:22px;justify-content:flex-end"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn primary" type="submit">Add bill</button></div></form>`;applyLanguage(d);d.showModal()}
function paymentForm(id){const b=bills.find(x=>x.id===id);if(!b){toast('Bill not found.');return}const paid=(b.payments||[]).reduce((n,p)=>n+Number(p.amount||0),0),remaining=Math.max(0,Number(b.amount)-paid),d=$('#modal'),today=new Date().toISOString().slice(0,10);d.innerHTML=`<div class="modal-head"><h2>Record a completed payment.</h2><button class="close" data-act="close" aria-label="Close">×</button></div><p><span data-i18n-ignore>${esc(b.supplier)}</span> · ${esc(b.id)}<br>Remaining balance: <strong>${money(remaining)}</strong></p><div class="notice amber" style="margin-bottom:18px">Record this only after the payment has been made outside Fieldwise.</div><form id="payment-form"><input type="hidden" name="billId" value="${esc(b.id)}"><div class="form-grid"><div><label for="pay-amount">Amount paid (₹)</label><input id="pay-amount" name="amount" type="number" min="1" max="${remaining}" step="1" value="${remaining}" required></div><div><label for="pay-date">Payment date</label><input id="pay-date" name="date" type="date" value="${today}" required></div><div><label for="pay-method">Payment method</label><select id="pay-method" name="method">${['UPI','Cash','Bank transfer','Cheque','Other'].map(x=>`<option value="${esc(x)}">${x}</option>`).join('')}</select></div><div><label for="pay-reference">Receipt / UTR reference (optional)</label><input id="pay-reference" name="reference" maxlength="40" placeholder="Do not enter PINs or OTPs"></div></div><div class="buttons" style="margin-top:22px;justify-content:flex-end"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn primary" type="submit">Save payment record</button></div></form>`;applyLanguage(d);d.showModal()}
function exportBilling(){const q=x=>JSON.stringify(String(x??'')),rows=[['Bill ID','Supplier','Category','Due date','Bill amount INR','Paid INR','Balance INR','Payment date','Method','Reference']];for(const b of bills){const ps=b.payments||[],paid=ps.reduce((n,p)=>n+Number(p.amount||0),0);if(ps.length)for(const p of ps)rows.push([b.id,b.supplier,b.category,b.dueDate,b.amount,paid,Math.max(0,b.amount-paid),p.date,p.method,p.reference]);else rows.push([b.id,b.supplier,b.category,b.dueDate,b.amount,0,b.amount,'','',''])}if(!bills.length)rows.push(['No bills recorded','','','','','','','','','']);const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(q).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='fieldwise-bills-and-payments.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Billing ledger exported as CSV.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act],[data-preset],[data-load],[data-delete],[data-pay]');if(!b)return;if(b.dataset.preset){tab=b.dataset.preset;state.risk={balanced:60,return:0,resilient:100}[tab];plan=FW.optimize(state);persist('fw-context',state);render();return}if(b.dataset.load!==undefined){const s=saved[+b.dataset.load];state={...s.context};plan=FW.optimize(state);persist('fw-context',state);location.hash='planner';render();toast('Saved assumptions restored.');return}if(b.dataset.pay!==undefined){paymentForm(b.dataset.pay);return}if(b.dataset.delete!==undefined){const i=+b.dataset.delete;const d=$('#modal');d.innerHTML=`<h2>Delete this saved record?</h2><p><span data-i18n-ignore>${esc(saved[i].name)}</span> will be removed from your saved plans.</p><div class="buttons">${button('Cancel','close')}<button class="btn primary" data-act="confirm-delete" data-index="${i}">Delete record</button></div>`;applyLanguage(d);d.showModal();return}switch(b.dataset.act){case'menu':$('.sidebar').classList.toggle('open');break;case'close':$('#modal').close();break;case'edit':edit();break;case'export':downloadAnalysisPdf();break;case'billing-add':billForm();break;case'billing-export':exportBilling();break;case'save':savePlan();break;case'confirm-delete':saved.splice(+b.dataset.index,1);persist('fw-plans',saved);$('#modal').close();render();toast('Record deleted.');break;case'risk':location.hash='finance';toast('Review the downside estimate and break-even lens.');break;case'soil':edit();break;case'cost':location.hash='planner';toast('Review the per-hectare assumptions before committing.');break;}});
document.addEventListener('input',e=>{const key=e.target.dataset.subscription;if(!key)return;subscription[key]=Number(e.target.value);persist('fw-subscription',subscription);const out=$('#sub-'+key+'-out');if(out)out.textContent=key==='farmers'?num(subscription[key]):money(subscription[key]);$('#subscription-results').innerHTML=subscriptionMetrics();applyLanguage($('#subscription-results'))});
document.addEventListener('change',e=>{if(e.target.dataset.task){let id=e.target.dataset.task;tasks=e.target.checked?[...new Set([...tasks,id])]:tasks.filter(t=>t!==id);persist('fw-tasks',tasks);toast('Checklist saved.')}});
document.addEventListener('submit',e=>{if(e.target.id==='bill-form'){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const amount=Number(f.amount);if(!Number.isFinite(amount)||amount<=0){toast('Enter a bill amount above ₹0.');return}bills.unshift({id:'FW-'+Date.now().toString().slice(-8),supplier:f.supplier.trim(),category:f.category,amount,dueDate:f.dueDate,createdAt:new Date().toISOString().slice(0,10),payments:[]});const ok=persist('fw-bills',bills);$('#modal').close();if(ok){render();toast('Bill added to your local ledger.')}}if(e.target.id==='payment-form'){e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),b=bills.find(x=>x.id===f.billId);if(!b){toast('Bill not found. Refresh and try again.');return}const amount=Number(f.amount),paid=(b.payments||[]).reduce((n,p)=>n+Number(p.amount||0),0),remaining=Number(b.amount)-paid;if(!Number.isFinite(amount)||amount<=0||amount>remaining){toast('Payment must be above ₹0 and no more than the remaining balance.');return}b.payments=b.payments||[];b.payments.push({amount,date:f.date,method:f.method,reference:f.reference.trim()});const ok=persist('fw-bills',bills);$('#modal').close();if(ok){render();toast('Completed payment recorded.')}}if(e.target.id==='farm-form'){e.preventDefault();const f=new FormData(e.target);let next={...state,...Object.fromEntries(f)};for(const k of ['area','budget','water','risk'])next[k]=+next[k];if(!Number.isFinite(next.area)||next.area<=0||next.budget<0||next.water<0){toast('Please enter valid farm constraints.');return}next.rain=0;next.price=0;state=next;plan=FW.optimize(state);persist('fw-context',state);$('#modal').close();render();toast('Farm updated. All decisions recalculated.')}if(e.target.id==='save-form'){e.preventDefault();saved.unshift({name:new FormData(e.target).get('planName'),kind:'plan',date:localDateKey(),context:{...state},a:plan.best.a,result:FW.evaluate(plan.best.a,state)});if(persist('fw-plans',saved)){toast('Saved to your portfolio.')}$('#modal').close();if(route==='portfolio')render()}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});window.addEventListener('online',syncBackend);window.addEventListener('offline',()=>syncStatus('Device only · sign in to sync',true));



function legacy_actionList(){return farmerActions.map((a,i)=>`<article class="farmer-action ${tasks.includes(a.id)?'is-done':''}"><span class="action-icon ${i===1?'amber':''}">${icon(a.ic,17)}</span><div class="farmer-action-copy"><div class="action-kicker">${a.due}</div><h3>${a.title}</h3><p>${a.desc}</p><p class="action-why">${a.why}</p><small>${a.cost}</small><label class="action-done"><input type="checkbox" class="check" data-task="${a.id}" ${tasks.includes(a.id)?'checked':''}> Mark reviewed</label></div><button class="btn action-open" data-act="${a.act}" data-i18n-ignore aria-label="${esc(translateUI('Open ' + a.title))}">${icon('arrow',15)}</button></article>`).join('')}
function legacy_seasonTimeline(){const stages=[['stage-before','Before sowing','Check soil, water and local prices.'],['stage-start','Establishment','Record emergence and update field observations.'],['stage-growth','During growth','Recheck water, weather and available cash when conditions change.'],['stage-harvest','Harvest and sale','Compare actual yield, costs and net sale value.']];return `<div class="season-timeline">${stages.map(([id,title,desc],i)=>`<label class="season-stage ${tasks.includes(id)?'is-done':''}"><span class="season-number">0${i+1}</span><input class="check" type="checkbox" data-task="${id}" ${tasks.includes(id)?'checked':''}><span class="season-stage-copy"><strong>${title}</strong><small>${desc}</small></span></label>`).join('')}</div><p class="timeline-note">Revisit the plan when observed weather, available water, quotations or cash limits change. Do not switch crops already planted based on this pre-sowing model.</p>`}
function comparisonCards(){const choices=[['economical','Lower cash outlay','Lowest modeled cultivation cost among feasible mixes.'],['waterwise','Use less irrigation','Lowest modeled seasonal irrigation among feasible mixes.'],['returnFocused','Higher expected return','Highest modeled average net return before risk adjustment.']];return `<div class="comparison-grid">${choices.map(([key,title,desc])=>{const p=plan.alternatives?.[key];if(!p)return `<article class="scenario-option"><h3>${title}</h3><p>No feasible mix is available under the current limits.</p></article>`;return `<article class="scenario-option"><div class="scenario-option-title"><span>${title}</span>${JSON.stringify(p.a)===JSON.stringify(plan.best?.a)?'<span class="pill">Same mix</span>':''}</div><p>${desc}</p><div class="scenario-metrics"><div><small>NET · P10–P90</small><strong>${money(p.p10)} to ${money(p.p90)}</strong></div><div><small>UPFRONT COST</small><strong>${money(p.cost)}</strong></div><div><small>WATER</small><strong>${num(p.water)} m³</strong></div></div><div class="scenario-crop-mix">${FW.crops.map((c,i)=>`${c.name} ${formatArea(p.a[i])}`).join(' · ')}</div></article>`}).join('')}</div>`}
function legacy_overview(){const p=plan.best;return head('A clearer plan for your season.','Your next steps, available resources and decision limits in one place.',button('Download analysis PDF','export',false,'down')+button('Update farm','edit',true,'settings'))+`<div class="hero"><div class="hero-copy"><div class="eyebrow">${icon('leaf',13)} YOUR SEASON, IN PERSPECTIVE</div><h2>Start with what your field can support.</h2><p>Use the plan as a starting point. Check local conditions and prices before spending.</p><a class="btn light" href="#planner">Compare plan choices ${icon('arrow',13)}</a></div><div class="hero-art">${fieldDiagram()}<span class="map-tag">Illustrative field plan · not satellite imagery</span></div></div>${!p?noPlan():`<div class="grid today-grid">${panel('Today on your farm','Three practical checks before changing the plan or committing money.',actionList())}${panel('Weather check','Keep the sky view simple and verify current conditions locally.',`<div class="weather-check-card"><span class="weather-symbol">${icon('sun',25)}</span><div><strong>No live forecast connected</strong><p>Check a trusted local forecast before irrigation, spraying or harvest.</p></div></div><div class="weather-check-tags"><span>Rain · verify locally</span><span>Wind · before spraying</span><span>Soil moisture · observe in field</span></div><a class="text-link" href="#evidence">See connected and missing evidence ↗</a>`)}</div><div class="stats">${stat('Expected net return',money(p.mean),'','Modeled average · synthetic assumptions','wallet')}${stat('Cash left after modeled cost',money(state.budget-p.cost),'','Does not include household or debt expenses','brief')}${stat('Planned irrigation',num(p.water),'m³',`${Math.round(p.water/Math.max(1,state.water)*100)}% of the entered allowance`,'water')}${stat('Downside estimate',money(p.p10),'','P10 simulation · not a calibrated probability','shield')}</div><div class="grid"><div>${featuredPanel('A balanced start to your season','Recommended land allocation',allocation(p),'<a class="text-link" href="#planner">Compare options ↗</a>')}<div class="evidence-card"><div class="evidence-card-head"><span class="eyebrow">EVIDENCE BEHIND THIS PLAN</span><span class="badge amber">Limited local confidence</span></div><div class="evidence-grid"><div><small>Farm context</small><strong>Entered by you</strong></div><div><small>Yield, price and cost</small><strong>Synthetic demo values</strong></div><div><small>Live weather, soil test and market</small><strong>Not connected</strong></div></div><p>Missing local evidence can change the result. Verify assumptions with a local adviser before spending.</p></div></div>${panel('Season outcomes','Modeled return range · illustrative, not a monthly cash forecast',chart(p)+`<div class="chart-labels"><span>Before sowing</span><span>Establishment</span><span>Growth</span><span>Harvest</span></div><div class="notice">${icon('info',13)} The line shows a scenario range across season stages; it does not predict when cash will arrive.</div>`,'<span class="legend"><span><i style="background:#285640"></i>Expected</span><span><i style="background:#d4dfcc"></i>Range</span></span>')}</div>${workspaceBillingWidget()}`}`}
function legacy_farm(){return head('Your farm, in context.','Keep the field size, water and budget realistic. Missing details can stay unknown.',button('Edit farm profile','edit',true,'settings'))+`<div class="grid equal">${panel(`<span data-i18n-ignore>${esc(state.name)}</span>`,`<span data-i18n-ignore>${esc(state.region)}</span> · demonstration inputs`,`<div class="field-map">${fieldDiagram()}</div><div class="metric-list"><div><span>Cultivated area</span><strong>${formatArea(state.area)}</strong></div><div><span>Soil type</span><strong>${esc(state.soil)}</strong></div><div><span>Available working budget</span><strong>${money(state.budget)}</strong></div><div><span>Seasonal water limit</span><strong>${num(state.water)} m³</strong></div></div>`,'<span class="badge amber">Demo profile</span>')}${panel('What is observed?','Separate your information from model assumptions.',`<div class="metric-list"><div><span>Land and resource limits</span><strong>Entered by you</strong></div><div><span>Yield, price and input costs</span><strong>Synthetic estimates</strong></div><div><span>Soil lab report and live forecast</span><strong>Not connected</strong></div><div><span>Local-fit confidence</span><strong>Limited</strong></div></div><div class="notice amber">Changing the location or soil label does not locally calibrate the crop coefficients. Add a measured soil or water observation when available.</div><div style="margin-top:20px">${actionList()}</div>`)}</div>`}
function legacy_planner(){const p=plan.best;return head('Compare choices before you commit.','Every option uses the same land, budget and water limits.',button('Save this plan','save',true,'plus'))+`<div class="tabs"><button data-preset="balanced" class="${tab==='balanced'?'active':''}">Balanced</button><button data-preset="return" class="${tab==='return'?'active':''}">Prioritize return</button><button data-preset="resilient" class="${tab==='resilient'?'active':''}">Protect the downside</button></div>`+(!p?noPlan():`<div class="grid"><div>${featuredPanel('Recommended crop mix','Risk preference: ${state.risk}/100 · ${plan.count} feasible mixes',allocation(p))}<div class="evidence-card"><span class="badge amber">Limited local confidence</span><p>This mix ranks highest for the selected risk preference. Crop yields, prices, costs and uncertainty are synthetic demo assumptions; verify local quotations and conditions.</p></div></div>${panel('Why this plan?',`All options meet the entered land, budget and water limits.`, `<div class="metric-list"><div><span>Modeled cost</span><strong>${money(p.cost)} / ${money(state.budget)}</strong></div><div><span>Modeled irrigation</span><strong>${num(p.water)} / ${num(state.water)} m³</strong></div><div><span>Expected net · P10–P90</span><strong>${money(p.mean)} · ${money(p.p10)} to ${money(p.p90)}</strong></div><div><span>Simulation loss frequency</span><strong>${p.loss.toFixed(1)}%*</strong></div></div><div class="notice">*Frequency in 240 synthetic draws. It is not a calibrated real-world probability. Long-term soil and rotation effects are not quantified.</div>`)}</div>${panel('Three ways to balance your limits','The same model, with a different priority for each option.',comparisonCards())}<div class="grid equal">${panel('Season timeline','Review each stage and mark checks you have completed.',seasonTimeline())}${panel('Crop-level assumptions','Illustrative per-hectare values · verify with current local sources.',`<div class="table-wrap"><table><thead><tr><th>CROP</th><th>LAND</th><th>YIELD / HA</th><th>PRICE / QUINTAL</th><th>COST / HA</th><th>WATER / HA</th></tr></thead><tbody>${FW.crops.map((c,i)=>`<tr><td><i class="crop-dot" style="background:${c.color}"></i>${c.name}</td><td>${formatArea(p.a[i])}</td><td>${c.yield} q</td><td>${money(c.price)}</td><td>${money(c.cost)}</td><td>${num(c.water)} m³</td></tr>`).join('')}</tbody></table></div><p class="timeline-note">These values are synthetic demonstration inputs, not official district recommendations.</p>`)}</div>`)}
function legacy_subscriptions(){return head('Support for the season.','Know what is available today and what is only a proposed paid service.',`<span class="badge amber">Checkout not connected</span>`)+`<div class="notice amber">This public prototype does not collect subscription payments. Current tools are open for demonstration; proposed paid services are not yet activated.</div><div class="grid equal" style="margin-top:22px"><article class="plan-card"><span class="pill">AVAILABLE IN THIS DEMO</span><h2>Fieldwise Essentials</h2><div class="plan-price">Free <small>for the prototype</small></div><ul><li>Farm context and editable constraints</li><li>Crop mix comparisons for cost, water and modeled return</li><li>Season checklist and local-evidence reminders</li><li>PDF farm analysis and bill ledger</li><li>Offline browser cache; account sync when signed in</li></ul><p class="tiny">No payment details are requested. Bill records only log payments made elsewhere.</p></article><article class="plan-card plan-card-plus"><span class="pill">PROPOSED · PRICE TO VALIDATE</span><h2>Fieldwise Season Plus</h2><div class="plan-price">₹300 <small>per farmer / year · test assumption</small></div><ul><li>Local-language seasonal guidance with source and date</li><li>Verified weather and mandi-price updates</li><li>Multi-season records and reminders</li><li>Optional review from a named agronomist or FPO partner</li></ul><p class="tiny">These services need working data connections and verified local partners before they can be offered.</p></article></div><div class="grid equal" style="margin-top:22px">${panel('How access could be funded','A lower-cost route for smallholder farmers.',`<div class="timeline"><div><small>FARMER GROUPS</small><h3>FPO or co-op sponsorship</h3><p>Group pricing and onboarding can lower the direct cost to a farmer.</p></div><div><small>OPTIONAL HUMAN SUPPORT</small><h3>Verified agronomist review</h3><p>Disclose the reviewer, price and limits of each consultation.</p></div><div><small>LOCAL PROGRAMS</small><h3>Pilot and implementation partnerships</h3><p>Work with farmer groups, universities or public programs to test impact.</p></div></div><div class="notice">Personal farm and payment records should never be sold. Any aggregate use needs informed consent and protection against identifying individual farms.</div>`)}${panel('What payment means here','No transaction happens inside this prototype.',`<p class="tiny">A future subscription should show its full price, billing period, cancellation process and support contact before checkout. The current site has no payment processor or paid access gate.</p><div class="privacy-callout">Farmers should be able to use essential safety and evidence information without a paid plan.</div>`)}</div>`}
function operator(){return head('Business workspace.','Private planning tools for the Fieldwise operator; not part of the farmer dashboard.',`<span class="badge">Owner account verified</span>`)+`<div class="privacy-callout">These business assumptions are visible only after the server verifies the owner account. They are planning scenarios, not revenue forecasts.</div><div class="grid" style="margin-top:22px">${panel('Test the subscription economics','Change the assumptions. Results update immediately.',`<div class="controls"><div class="control"><label for="sub-farmers">Paying farmers <output id="sub-farmers-out">${num(subscription.farmers)}</output></label><input id="sub-farmers" type="range" min="10" max="10000" step="10" value="${subscription.farmers}" data-subscription="farmers"><div class="range-labels"><span>10</span><span>10,000</span></div></div><div class="control"><label for="sub-fee">Annual price per farmer <output id="sub-fee-out">${money(subscription.fee)}</output></label><input id="sub-fee" type="range" min="0" max="2000" step="50" value="${subscription.fee}" data-subscription="fee"><div class="range-labels"><span>Free</span><span>${money(2000)}</span></div></div><div class="control"><label for="sub-service">Service cost per farmer / year <output id="sub-service-out">${money(subscription.service)}</output></label><input id="sub-service" type="range" min="0" max="1000" step="20" value="${subscription.service}" data-subscription="service"><div class="range-labels"><span>₹0</span><span>₹1,000</span></div></div><div class="control"><label for="sub-fixed">Annual fixed costs <output id="sub-fixed-out">${money(subscription.fixed)}</output></label><input id="sub-fixed" type="range" min="0" max="1000000" step="10000" value="${subscription.fixed}" data-subscription="fixed"><div class="range-labels"><span>₹0</span><span>₹10 lakh</span></div></div></div><div class="notice">Gross revenue = farmers × fee. Contribution subtracts service cost; estimated operating result also subtracts fixed costs. Taxes, payment fees, acquisition, bad debt and founder salary are excluded.</div>`)}${panel('Illustrative annual outcome','Planning worksheet only · figures are not a revenue forecast.',`<div id="subscription-results">${subscriptionMetrics()}</div>`)}<div class="grid equal">${panel('Revenue paths to validate','Keep farm advice independent from commercial placement.',`<div class="timeline"><div><small>01 / FARMER GROUPS</small><h3>FPO or co-op licence</h3><p>Group-paid access can lower the farmer’s upfront cost.</p></div><div><small>02 / HUMAN SUPPORT</small><h3>Named agronomist review</h3><p>Offer paid reviews through verified partners and disclose the fee.</p></div><div><small>03 / PILOT PARTNERS</small><h3>Local validation contracts</h3><p>Work with FPOs, universities or public programs to test the product.</p></div></div>`)}${panel('Validation before pricing','Test with farmers before setting a subscription price.',`<p class="tiny">Measure farmer willingness to pay, renewal, affordability and whether net farm outcomes improve. Avoid selling individual records; get informed consent before using aggregate data.</p>`)}</div></div>`}
function legacy_edit(){const d=$('#modal'),unit=state.areaUnit==='acre'?'acre':'ha',display=unit==='acre'?state.area*areaFactor:state.area;d.innerHTML=`<div class="modal-head"><h2>Your farm, in context.</h2><button class="close" data-act="close" aria-label="Close">×</button></div><p>Enter what you know. Leave the decision evidence incomplete if you do not have a measurement.</p><form id="farm-form"><div class="form-grid"><div class="full"><label for="name">Farm name</label><input id="name" name="name" value="${esc(state.name)}" required maxlength="50"></div><div class="full"><label for="region">Village, taluka or district</label><input id="region" name="region" value="${esc(state.region)}" required maxlength="80"></div><div><label for="area">Cultivated area</label><input id="area" name="area" type="number" min="0.1" max="${unit==='acre'?'49.42':'20'}" step="${unit==='acre'?'0.01':'0.1'}" data-unit="${unit}" value="${display.toFixed(2)}" required></div><div><label for="areaUnit">Area unit</label><select id="areaUnit" name="areaUnit"><option value="ha" ${unit==='ha'?'selected':''}>Hectares</option><option value="acre" ${unit==='acre'?'selected':''}>Acres</option></select></div><div><label for="budget">Available budget (₹)</label><input id="budget" name="budget" type="number" min="0" max="10000000" step="100" value="${state.budget}" required></div><div><label for="water">Seasonal irrigation limit (m³)</label><input id="water" name="water" type="number" min="0" max="500000" step="10" value="${state.water}" required></div><div><label for="soil">Soil type, if known</label><select id="soil" name="soil">${['Medium black','Deep black','Sandy loam','Unknown'].map(v=>`<option value="${v}" ${v===state.soil?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="evidence">Evidence completeness</label><select id="evidence" name="evidence">${['partial','missing'].map(v=>`<option value="${v}" ${v===state.evidence?'selected':''}>${v==='partial'?'Some details known':'Key details missing'}</option>`).join('')}</select></div><div><label for="risk">Risk preference (0–100)</label><input id="risk" name="risk" type="number" min="0" max="100" value="${state.risk}" required></div></div><div class="notice">Area is converted to hectares for the model. Currency is Indian rupees; water is cubic metres.</div><div class="buttons" style="margin-top:24px;justify-content:flex-end"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn primary" type="submit">Update and recalculate ${icon('arrow',14)}</button></div></form>`;applyLanguage(d);d.showModal()}
function legacy_render(){route=location.hash.slice(1)||'overview';if(route==='operator'&&!canManage){if(!accessChecked){$('#app').innerHTML=`<main class="access-check"><span class="brand-mark">${icon('leaf',23)}</span><h1>Checking account access</h1><p>Business tools open only for the verified owner account.</p></main>`;return}location.hash='overview';return}if(!navs.some(n=>n[0]===route)){location.hash='overview';return}const visibleNavs=navs.filter(n=>n[0]!=='operator'||canManage),name=navs.find(n=>n[0]===route)[2],unitPrefs=[['en','English'],['mr','मराठी'],['hi','हिन्दी']];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#overview"><span class="brand-mark">${icon('leaf',23)}</span>fieldwise<span class="brand-dot">.</span></a><div class="nav-label">YOUR WORKSPACE</div><nav class="nav">${visibleNavs.map(([id,ic,label])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ic)}${label}</a>`).join('')}</nav><div class="side-bottom"><div class="field-note"><strong>${icon('leaf',14)} Rooted in better decisions.</strong><span>A little more clarity.<br>A more resilient season.</span><a href="#evidence">Our approach ${icon('arrow',12)}</a></div><div class="profile"><span class="avatar">FW</span><div><strong data-i18n-ignore>${esc(state.farmerName||state.name)}</strong><br><small data-i18n-ignore>${esc(state.region)}</small></div></div></div></aside><div class="main"><header class="topbar"><div class="breadcrumbs"><button class="mobile-menu" data-act="menu" aria-label="Open navigation">${icon('menu',20)}</button><span>Workspace</span><span>/</span><strong>${name}</strong></div><div class="top-right"><label class="language-wrap"><span class="sr-only">Language</span><select id="language-select" aria-label="Choose language" title="Core dashboard labels are available in English, Marathi and Hindi; technical details remain in English.">${unitPrefs.map(([id,label])=>`<option value="${id}" ${prefs.language===id?'selected':''}>${label}</option>`).join('')}</select></label><span class="date muted">Rabi planning</span><span id="sync-status" class="badge amber" title="Farm records sync only within a signed-in account; offline edits stay on this device until reconnected.">${currentSyncLabel}</span></div></header><main class="content"><div class="privacy-callout" id="privacy-hint" role="note">Public demo · browser-only until account sync is available. Avoid entering sensitive details on a shared device.</div>${({overview,farm,planner,resources,finance,billing,subscriptions,evidence,portfolio,operator}[route])()}<footer class="footer"><span>${icon('leaf',12)} Fieldwise · Farm intelligence, grounded.</span><span>Illustrative inputs · transparent assumptions · verify locally</span></footer></main></div><nav class="mobile-dock" aria-label="Quick navigation">${[['overview','grid','Home'],['farm','field','My farm'],['planner','leaf','Plan'],['billing','wallet','Bills']].map(([id,ic,label])=>`<a href="#${id}" class="${route===id?'active':''}">${icon(ic,18)}<span>${label}</span></a>`).join('')}</nav></div>`;syncStatus(currentSyncLabel,currentSyncLabel.includes('Device')||currentSyncLabel.includes('Offline')||currentSyncLabel.includes('Local'));applyLanguage()}
function legacy_syncStatus(label,offline=false){currentSyncLabel=label;const el=$('#sync-status');if(el){el.textContent=label;el.className=offline?'badge amber':'badge'}const hint=$('#privacy-hint');if(hint){hint.textContent=label==='Cloud synced'||label==='Saving…'?'Cloud sync is account-scoped; each signed-in account has separate records. Sign out before leaving a shared device.':'Public demo · local changes stay in this browser until a signed-in account syncs. Avoid sensitive entries on shared devices.'}}
document.addEventListener('change',e=>{if(e.target.id==='areaUnit'){const input=$('#area'),previous=input?.dataset.unit||'ha',next=e.target.value;if(input&&previous!==next){const value=Number(input.value);input.value=(next==='acre'?value*areaFactor:value/areaFactor).toFixed(2);input.dataset.unit=next;input.max=next==='acre'?'49.42':'20';input.step=next==='acre'?'0.01':'0.1'}}},true);
document.addEventListener('submit',e=>{if(e.target.id==='farm-form'){const input=e.target.elements.area,unit=e.target.elements.areaUnit.value;if(unit==='acre'&&input){input.value=String(Number(input.value)/areaFactor)} }},true);

document.addEventListener('change',e=>{if(!e.target.dataset.task)return;const row=e.target.closest('.season-stage,.farmer-action');if(row)row.classList.toggle('is-done',e.target.checked)},true);

// Farmer day-to-day improvements: guided setup, stage-aware tasks, field records and accessible controls.
const stageCatalog=[
  {id:'before',label:'Before sowing',mr:'पेरणीपूर्वी',hi:'बुवाई से पहले'},
  {id:'sowing',label:'Sowing',mr:'पेरणी',hi:'बुवाई'},
  {id:'growing',label:'Growing',mr:'वाढीचा काळ',hi:'फसल बढ़ने का समय'},
  {id:'harvest',label:'Harvest',mr:'कापणी',hi:'कटाई'},
  {id:'post',label:'After harvest',mr:'कापणीनंतर',hi:'कटाई के बाद'}
];
const stageLabel=id=>translateUI(stageCatalog.find(s=>s.id===id)?.label||stageCatalog[0].label);
function formatSavedDate(value){const raw=String(value??'').trim(),digits=raw.replace(/[०-९]/g,ch=>String('०१२३४५६७८९'.indexOf(ch)));let d;if(/^\d{4}-\d{2}-\d{2}$/.test(digits)){d=new Date(digits+'T00:00:00')}else{const parts=/^(\d{1,2})[\/. -](\d{1,2})[\/. -](\d{4})$/.exec(digits);if(parts)d=new Date(Number(parts[3]),Number(parts[2])-1,Number(parts[1]));else d=new Date(raw)}return d&&!Number.isNaN(d.getTime())?d.toLocaleDateString(localeForUI()):raw}
const localDateKey=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const dailyActions={
 before:[
  {id:'soil',title:'Check soil and water for this plot',desc:'Use your own field observation or a soil and water test if you have one.',why:'The demo cannot test your soil or confirm irrigation supply.',cost:'No purchase needed to review this step.',act:'soil',ic:'field'},
  {id:'risk',title:'Review the lower result before spending',desc:'Keep money aside for household needs and unexpected costs.',why:'The range is a simulation, not a measured forecast.',cost:'No purchase needed to review this step.',act:'risk',ic:'shield'},
  {id:'cost',title:'Ask for today’s local input prices',desc:'Check seed, labor and input prices with a supplier you trust.',why:'There is no live supplier or market price feed.',cost:'Get a quote before committing.',act:'cost',ic:'wallet'}
 ],
 sowing:[
  {id:'sowrecord',title:'Write down what you planted',desc:'Record the crop, date and area while it is fresh.',why:'The planner compares next-season options; it does not track planted crops automatically.',cost:'No purchase needed.',act:'journal',ic:'book'},
  {id:'seedcheck',title:'Keep the seed label or receipt',desc:'Save the variety name and purchase details for later review.',why:'The demo does not verify seed quality or suitability.',cost:'No purchase needed.',act:'journal',ic:'check'},
  {id:'waterstart',title:'Check water before the first irrigation',desc:'Use your field observation and local advice to decide when to irrigate.',why:'No live weather or soil-moisture sensor is connected.',cost:'Avoid irrigating from this model alone.',act:'journal',ic:'water'}
 ],
 growing:[
  {id:'moisture',title:'Check field moisture before irrigating',desc:'Walk the plot and compare with your usual local practice.',why:'Fieldwise has no live soil-moisture reading.',cost:'No purchase needed to check.',act:'journal',ic:'water'},
  {id:'observe',title:'Record what changed in the crop',desc:'Note a visible change, date and plot so you can discuss it with a local adviser.',why:'This prototype does not diagnose pests or disease.',cost:'Do not buy a treatment based on this demo.',act:'journal',ic:'field'},
  {id:'dues',title:'Check bills due before another purchase',desc:'Compare the next payment with the cash you can use this week.',why:'Crop returns are estimates, not cash in hand.',cost:'Open your bill book.',act:'billing',ic:'wallet'}
 ],
 harvest:[
  {id:'harvestrecord',title:'Record the amount you actually harvested',desc:'Enter the weighed amount and date in your field journal.',why:'Actual harvest is not connected to a scale or market.',cost:'Use a measured weight when available.',act:'journal',ic:'book'},
  {id:'localprice',title:'Check the local selling price',desc:'Compare a current local quote after transport and fees.',why:'No live mandi price is connected.',cost:'Open an official market reference.',act:'cost',ic:'chart'},
  {id:'salecost',title:'Include selling and transport costs',desc:'Keep receipts so the final amount is easier to compare.',why:'These costs are not included in the crop estimate.',cost:'Record only amounts actually paid.',act:'journal',ic:'wallet'}
 ],
 post:[
  {id:'compareactual',title:'Compare actual spending with the plan',desc:'Add costs and water you used to the field journal.',why:'A partial log is not a complete season total.',cost:'No purchase needed.',act:'journal',ic:'chart'},
  {id:'closebills',title:'Review remaining supplier balances',desc:'Mark only completed payments in your bill book.',why:'Fieldwise does not move money or verify settlement.',cost:'Use your bank or agreed payment method separately.',act:'billing',ic:'wallet'},
  {id:'nextnotes',title:'Save one lesson for next season',desc:'Note what worked, what changed and what you would check earlier.',why:'Your notes help you compare plans; they do not calibrate the model.',cost:'No purchase needed.',act:'journal',ic:'book'}
 ]
};
function statusForAction(id){return actionStates&&typeof actionStates==='object'?actionStates[id]||null:null}
function actionControls(id){return `<div class="action-controls"><button class="btn action-status" data-action-status="${id}" data-status="done">Done</button><details class="action-more"><summary>More</summary><div class="action-more-menu"><button class="btn action-status" data-action-status="${id}" data-status="snooze">Tomorrow</button><button class="btn action-status quiet" data-action-status="${id}" data-status="skip">Not relevant</button></div></details></div>`}
function actionList(){
 const items=dailyActions[state.stage]||dailyActions.before,today=localDateKey();
 const active=items.filter(a=>{const s=statusForAction(a.id);return !s||s.status==='pending'||(s.status==='snoozed'&&(s.until||'')<=today)});
 const resting=items.filter(a=>{const s=statusForAction(a.id);return s&&(s.status==='done'||s.status==='skipped'||(s.status==='snoozed'&&(s.until||'')>today))});
 const rows=active.map(a=>`<article class="farmer-action"><span class="action-icon">${icon(a.ic,17)}</span><div class="farmer-action-copy"><h3>${a.title}</h3><p>${a.desc}</p><details class="action-context"><summary>Why / cost</summary><p>${a.why}</p><small>${a.cost}</small></details>${actionControls(a.id)}</div><button class="btn action-open" data-jump="${a.act}" data-i18n-ignore aria-label="${esc(translateUI('Open ' + a.title))}">${icon('arrow',15)}</button></article>`).join('');
 const restingRows=resting.map(a=>{const s=statusForAction(a.id),label=s.status==='done'?'Done':s.status==='skipped'?'Not relevant':'Snoozed until tomorrow';return `<div class="resting-action"><span><strong>${a.title}</strong><small>${label}</small></span><button class="btn" data-restore-action="${a.id}">Show again</button></div>`}).join('');
 return `<div class="today-action-list" id="today-actions"><div class="today-count"><strong>${active.length?`${active.length} checks for this stage`:'Your checks are clear for today'}</strong><span>${stageLabel(state.stage)}</span></div>${rows||`<div class="empty compact-empty"><p>Use the field journal to record what happens next.</p><a href="#journal" class="text-link">Open field journal ${icon('arrow',13)}</a></div>`}${resting.length?`<details class="resting-list"><summary>Done, snoozed or skipped (${resting.length})</summary>${restingRows}</details>`:''}</div>`;
}
function seasonTimeline(){return `<div class="season-timeline">${stageCatalog.map((s,i)=>`<label class="season-stage ${state.stage===s.id?'is-current':''} ${tasks.includes('stage-'+s.id)?'is-done':''}"><span class="season-number">0${i+1}</span><input class="check" type="checkbox" data-task="stage-${s.id}" ${tasks.includes('stage-'+s.id)?'checked':''} aria-label="Mark ${s.label} checklist reviewed"><span class="season-stage-copy"><strong>${s.label}</strong><small>${state.stage===s.id?'Current stage · ':''}${s.id==='before'?'Set up the plot and check local prices.':s.id==='sowing'?'Record the crop, date and area planted.':s.id==='growing'?'Check the field and available water.':s.id==='harvest'?'Record weighed harvest and selling costs.':'Review bills and keep lessons for next season.'}</small></span></label>`).join('')}</div><p class="timeline-note">If your crop is already planted, use the crop mix only as a next-season comparison. Recheck local conditions before spending or changing a plan.</p>`}
function setupPrompt(){return state.profileComplete?'' : `<div class="setup-prompt"><div><span class="eyebrow">START HERE · SAMPLE PROFILE</span><h2>Add your farm details</h2><p>These are sample numbers. Add your field, budget and water to make the plan yours.</p></div>${button('Set up my farm','edit',true,'settings')}</div>`}
function overviewLegacy(){
 const p=plan.best,stage=stageLabel(state.stage),starter=state.profileComplete?'Your farm, one clear next step at a time.':'A simple starting point for your farm.';
 const returnLabel=state.stage==='before'?'Possible net income':'Example for next season';
 const allocateTitle=state.stage==='before'?'A balanced start to your season':'A possible mix for next season';
 return head('Your farm, one clear next step at a time.','Today’s checks change with your crop stage. Keep local observations and prices close.',button('Download farm summary PDF','export',false,'down')+button('Update farm details','edit',true,'settings'))+
 setupPrompt()+`<div class="hero"><div class="hero-copy"><div class="eyebrow">${icon('leaf',13)} YOUR FIELD · ${stage.toUpperCase()}</div><h2>${starter}</h2><p>Check what applies to your field today. Estimates are a starting point; local conditions guide real farm decisions.</p><a class="btn light" href="#journal">Record today’s field update ${icon('arrow',13)}</a></div><div class="hero-art">${fieldDiagram()}<span class="map-tag">Simple field plan · example only</span></div></div>${!p?noPlan():`<div class="grid today-grid">${panel('Today on your farm','A few practical checks for this point in the season.',actionList())}${panel('Check the sky','No forecast is connected to this farm yet.',`<div class="weather-check-card"><span class="weather-symbol">${icon('sun',25)}</span><div><strong>Check your local forecast</strong><p>Before irrigation, spraying or harvest, confirm rain and wind with a trusted local source.</p></div></div><a class="btn weather-source" href="https://agromet.imd.gov.in/index.php/login/adv_status_index" target="_blank" rel="noopener">Open IMD farm advisories ${icon('arrow',13)}</a><p class="weather-note">Official link · Fieldwise does not fetch or refresh forecast data.</p>`)}</div><div class="stats">${stat(returnLabel,money(p.mean),'','Illustrative average after modeled crop costs','wallet')}${stat('Budget left in this plan',money(state.budget-p.cost),'','Does not include household costs or debt','brief')}${stat('Water in this plan',num(p.water),'m³',`${Math.round(p.water/Math.max(1,state.water)*100)}% of the limit you entered`,'water')}${stat('Lower example result',money(p.p10),'','One result from synthetic simulation runs','shield')}</div><div class="grid"><div>${featuredPanel(allocateTitle,'Compare before sowing; keep this as a next-season option if crops are already planted.',allocation(p),'<a class="text-link" href="#planner">Compare choices ↗</a>')}<div class="evidence-card"><div class="evidence-card-head"><span class="eyebrow">WHERE THESE NUMBERS COME FROM</span><span class="badge amber">Example values</span></div><div class="evidence-grid"><div><small>Farm details</small><strong>${state.profileComplete?'Entered by you':'Sample profile'}</strong></div><div><small>Crop yield, price and costs</small><strong>Illustrative assumptions</strong></div><div><small>Live weather, soil test and market</small><strong>Not connected</strong></div></div><p>Check local quotations and field conditions with a trusted adviser before spending.</p></div></div>${panel('Possible season result','A range from example runs · not a monthly cash forecast',chart(p)+`<div class="chart-labels"><span>Before sowing</span><span>Crop starts</span><span>Growth</span><span>Harvest</span></div><details class="plain-details"><summary>How to read this</summary><p>The middle line is the model average. The shaded area shows a range from synthetic runs. It does not predict the date money will arrive.</p></details>`,'<span class="legend"><span><i style="background:#285640"></i>Average</span><span><i style="background:#d4dfcc"></i>Range</span></span>')}</div>${workspaceBillingWidget()}`}`;
}
function farm(){const stage=stageLabel(state.stage);return head('My farm','Add only what you know. You can leave soil details unknown.',button('Edit farm details','edit',true,'settings'))+setupPrompt()+`<div class="grid equal">${panel(`<span data-i18n-ignore>${esc(state.name)}</span>`,`<span data-i18n-ignore>${esc(state.region)}</span> · ${stage}`,`<div class="field-map">${fieldDiagram()}</div><div class="metric-list"><div><span>Field area</span><strong>${formatArea(state.area)}</strong></div><div><span>Crop stage</span><strong>${stage}</strong></div><div><span>Soil type</span><strong>${esc(state.soil)}</strong></div><div><span>Cash available for this season</span><strong>${money(state.budget)}</strong></div><div><span>Water available for this season</span><strong>${num(state.water)} m³</strong></div></div>`,'<span class="badge amber">Your entries + sample crop values</span>')}${panel('What is used in the plan?','Know what came from you and what is still an example.',`<div class="metric-list"><div><span>Plot, budget and water limit</span><strong>${state.profileComplete?'Entered by you':'Sample values'}</strong></div><div><span>Soil label</span><strong>${esc(state.soil)} · not lab verified</strong></div><div><span>Crop yield, price and costs</span><strong>Synthetic examples</strong></div><div><span>Live forecast or mandi price</span><strong>Not connected</strong></div></div><div class="notice amber">Location and soil labels do not calibrate the model. When crops are already planted, use its crop mix only for next-season comparison.</div><a class="btn" href="#evidence">See data sources and limits ${icon('arrow',13)}</a>`)}</div>${panel('Season steps','Mark checks you have reviewed. The current crop stage guides today’s list.',seasonTimeline())}`}
function journal(){
 const p=plan.best,entries=Array.isArray(fieldLog)?fieldLog.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')):[];
 const actualCost=entries.reduce((n,x)=>n+Number(x.cost||0),0),actualWater=entries.reduce((n,x)=>n+Number(x.water||0),0),actualYield=entries.reduce((n,x)=>n+Number(x.yieldQ||0),0),actualSale=entries.reduce((n,x)=>n+Number(x.yieldQ||0)*Number(x.price||0),0);
 const plannedYield=p?p.yields.reduce((sum,y,i)=>sum+y*p.a[i],0):0,today=localDateKey();
 const actualCard=(label,value,planValue,unit)=>`<div class="actual-card"><small>${label}</small><strong>${value}</strong><span>${planValue===null?'No estimate':`Plan estimate: ${planValue}${unit}`}</span></div>`;
 return head('Field journal','Record what actually happened. Use the same units each time so you can compare it with the plan.',button('Download farm summary PDF','export',false,'down'))+`<div class="privacy-callout">Your entries stay on this device until you sign in to sync. They are not sent to an adviser or buyer. Record only actual amounts; bill entries and field costs can otherwise be counted twice.</div><div class="grid journal-grid"><section class="panel"><div class="panel-head"><div><h2>Add a field update</h2><p>A quick record for today’s costs, water and harvest.</p></div><span class="pill">${entries.length} ${entries.length===1?'entry':'entries'}</span></div><form id="journal-form"><div class="form-grid"><div><label for="log-date">Date</label><input type="date" id="log-date" name="date" value="${today}" required></div><div><label for="log-stage">Crop stage</label><select id="log-stage" name="stage">${stageCatalog.map(s=>`<option value="${s.id}" ${state.stage===s.id?'selected':''}>${s.label}</option>`).join('')}</select></div><div><label for="log-cost">Money actually spent (₹)</label><input id="log-cost" name="cost" type="number" min="0" max="10000000" step="1" inputmode="decimal" placeholder="0"></div><div><label for="log-water">Water actually used (m³)</label><input id="log-water" name="water" type="number" min="0" max="500000" step="1" inputmode="decimal" placeholder="0"></div><div><label for="log-yield">Harvest weighed (quintals)</label><input id="log-yield" name="yieldQ" type="number" min="0" max="1000000" step="0.1" inputmode="decimal" placeholder="Leave blank until harvest"></div><div><label for="log-price">Sale price (₹ per quintal)</label><input id="log-price" name="price" type="number" min="0" max="1000000" step="1" inputmode="decimal" placeholder="Optional"></div><div class="full"><label for="log-note">What did you observe? (optional)</label><textarea id="log-note" name="note" maxlength="500" rows="3" placeholder="Example: rain after irrigation, supplier quote, crop change"></textarea></div></div><p class="tiny">Numbers are optional. Leave a field blank if you did not measure it.</p><div class="buttons" style="margin-top:16px"><button type="submit" class="btn primary">Save field update ${icon('check',14)}</button></div></form></section><section class="panel"><div class="panel-head"><div><h2>Actual so far vs plan</h2><p>Partial records are compared only with the full-season estimate.</p></div></div><div class="actual-grid">${actualCard('Money recorded',money(actualCost),p?money(p.cost):null,'')}${actualCard('Water recorded',`${num(actualWater)} m³`,p?num(p.water):null,' m³')}${actualCard('Harvest recorded',`${actualYield.toFixed(1)} q`,p?`${plannedYield.toFixed(1)} q`:null,' q')}${actualCard('Sale amount recorded',money(actualSale),null,'')}</div><details class="plain-details"><summary>What this comparison means</summary><p>Costs and water are running totals from entries you saved. The planned values cover a whole season. Yield comparisons use synthetic crop assumptions. This is a recordkeeping aid, not an independent yield forecast.</p></details></section></div>${panel('Recent field updates',entries.length?'Newest entries first · this device and your signed-in account': 'Your first field update will appear here.',entries.length?`<div class="journal-entries">${entries.map(x=>`<article class="journal-entry"><div class="journal-entry-top"><strong>${new Date((x.date||today)+'T00:00:00').toLocaleDateString(localeForUI(),{day:'numeric',month:'short',year:'numeric'})} · ${stageLabel(x.stage)}</strong><button class="btn quiet" data-log-delete="${esc(x.id)}" aria-label="Delete field entry">Delete</button></div><div class="journal-facts">${x.cost?`<span>Spent ${money(x.cost)}</span>`:''}${x.water?`<span>Water ${num(x.water)} m³</span>`:''}${x.yieldQ?`<span>Harvest ${Number(x.yieldQ).toFixed(1)} q</span>`:''}${x.yieldQ&&x.price?`<span>Sale value ${money(Number(x.yieldQ)*Number(x.price))}</span>`:''}</div>${x.note?`<p data-i18n-ignore>${esc(x.note)}</p>`:''}</article>`).join('')}</div>`:`<div class="empty compact-empty"><p>Save the first update when you have a real observation or amount to record.</p></div>`)}`;
}
function subscriptionsLegacy(){return head('Plans for farmers','See what works in this demo and what would need to be built before anyone is charged.',`<span class="badge amber">No checkout or active subscription</span>`)+`<div class="notice amber">There is no payment form, trial, renewal or paid access gate on Fieldwise today. The ₹300/year amount is only a pricing hypothesis; it is not a live offer.</div><div class="grid equal" style="margin-top:20px"><article class="plan-card"><span class="pill">AVAILABLE NOW · FREE DEMO</span><h2>Fieldwise Essentials</h2><div class="plan-price">₹0 <small>in this prototype</small></div><ul><li>Farm details and crop-stage checklist</li><li>Example crop comparisons within entered limits</li><li>Field journal and bill book</li><li>PDF summary and offline browser cache</li><li>Sign-in account sync where available</li></ul><p class="tiny">Advice, data links and records are not independently verified or delivered by a paid team.</p></article><article class="plan-card plan-card-plus"><span class="pill">FUTURE IDEA · NOT AVAILABLE</span><h2>Season support</h2><div class="plan-price">₹300 <small>per year · untested assumption</small></div><ul><li>Local forecast and mandi updates with source and timestamp</li><li>Marathi and Hindi seasonal guidance</li><li>Multi-season records and reminders</li><li>Optional review by a named local agriculture adviser</li></ul><p class="tiny">Each benefit needs its own verified data source, service partner, support process and affordability test first.</p></article></div>${panel('Before a real subscription starts','Farmers should know exactly what they receive and how to stop paying.',`<div class="metric-list"><div><span>Price and billing period</span><strong>Show the full ₹ amount before checkout</strong></div><div><span>Renewal and cancellation</span><strong>Explain dates, refunds and how to cancel</strong></div><div><span>Data and privacy</span><strong>Never sell a farmer’s identifiable records</strong></div><div><span>Essential safety information</span><strong>Keep it available without payment</strong></div></div><div class="notice">No charge is made here. A verified payment provider and merchant account are required before subscriptions can be offered.</div>`)}<div class="grid equal">${panel('A practical farmer pilot','Test the main tasks with farmers before setting a price.',`<ol class="pilot-list"><li>Set up a village, plot size, crop stage and water limit without help.</li><li>Find the next useful check for today and explain why it appears.</li><li>Record one expense or water use in the field journal.</li><li>Find the official weather or market source and tell whether data is live.</li><li>Ask the farmer to explain what the plan does not know.</li></ol><p class="tiny">Record task completion, time, confusion and preferred language. Test with a local farmer group and agronomist; the prototype has not had field usability testing.</p>`)}</div>`}
function edit(){const d=$('#modal'),unit=state.areaUnit==='acre'?'acre':'ha',display=unit==='acre'?state.area*areaFactor:state.area;d.innerHTML=`<div class="modal-head"><h2>Set up your farm</h2><button class="close" data-act="close" aria-label="Close">×</button></div><p>Start with what you know. Choose “Unknown” if you do not have a measurement.</p><form id="farm-form"><div class="form-grid"><div class="full"><label for="name">Farm or plot name</label><input id="name" name="name" value="${esc(state.name)}" required maxlength="50"></div><div class="full"><label for="region">Village, taluka or district</label><input id="region" name="region" value="${esc(state.region)}" required maxlength="80"></div><div><label for="area">Cultivated area</label><input id="area" name="area" type="number" min="0.1" max="${unit==='acre'?'49.42':'20'}" step="${unit==='acre'?'0.01':'0.1'}" data-unit="${unit}" value="${display.toFixed(2)}" required></div><div><label for="areaUnit">Area unit</label><select id="areaUnit" name="areaUnit"><option value="ha" ${unit==='ha'?'selected':''}>Hectares</option><option value="acre" ${unit==='acre'?'selected':''}>Acres</option></select></div><div><label for="budget">Cash available for the season (₹)</label><input id="budget" name="budget" type="number" min="0" max="10000000" step="100" value="${state.budget}" required></div><div><label for="water">Water available for the season (m³)</label><input id="water" name="water" type="number" min="0" max="500000" step="10" value="${state.water}" required></div><div><label for="soil">Soil type, if known</label><select id="soil" name="soil">${['Medium black','Deep black','Sandy loam','Unknown'].map(v=>`<option value="${v}" ${v===state.soil?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="evidence">How much do you know about these inputs?</label><select id="evidence" name="evidence">${['partial','missing'].map(v=>`<option value="${v}" ${v===state.evidence?'selected':''}>${v==='partial'?'Some details are measured':'Several details are unknown'}</option>`).join('')}</select></div><div><label for="risk">How much risk can you manage?</label><select id="risk" name="risk">${[['0','Prefer lower risk'],['30','Some risk'],['60','Balanced'],['100','Accept more risk']].map(([v,t])=>`<option value="${v}" ${Number(state.risk)===Number(v)?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="stage">What is happening in this field now?</label><select id="stage" name="stage">${stageCatalog.map(s=>`<option value="${s.id}" ${state.stage===s.id?'selected':''}>${s.label}</option>`).join('')}</select></div></div><div class="notice">Area is converted for the calculation. Crop yields, prices and input costs are still examples. If a crop is already planted, the mix below is for next-season comparison only.</div><div class="buttons" style="margin-top:20px;justify-content:flex-end"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn primary" type="submit">Save farm details ${icon('arrow',14)}</button></div></form>`;applyLanguage(d);d.showModal()}
