function announcePageLegacy(){if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){toast('Read-aloud is not available in this browser.');return}if(window.speechSynthesis.speaking){window.speechSynthesis.cancel();return}const parts=[$('.heading h1')?.textContent,$('.heading>div>p')?.textContent,$('#today-actions')?.innerText,$('#journal-form')?.innerText].filter(Boolean),text=parts.join('. ').replace(/\s+/g,' ').trim();if(!text){toast('There is no page text to read.');return}const u=new SpeechSynthesisUtterance(text),lang=prefs.language||'en';u.lang=lang==='mr'?'mr-IN':lang==='hi'?'hi-IN':'en-IN';u.rate=.9;window.speechSynthesis.cancel();window.speechSynthesis.speak(u)}
async function speakPage(){if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){toast('Read-aloud is not available in this browser.');return}const synth=window.speechSynthesis;if(synth.speaking){synth.cancel();return}const lang=prefs.language||'en';let voices=synth.getVoices();if(lang==='mr'&&!voices.length){await Promise.race([new Promise(resolve=>synth.addEventListener('voiceschanged',resolve,{once:true})),new Promise(resolve=>setTimeout(resolve,500))]);voices=synth.getVoices()}const voice=voices.find(v=>lang==='mr'?/^mr(?:-|$)/i.test(v.lang):lang==='hi'?/^hi(?:-|$)/i.test(v.lang):/^en(?:-|$)/i.test(v.lang));if(lang==='mr'&&!voice){toast('A Marathi voice is not available on this device. Add a Marathi voice in device settings.');return}const main=$('.content'),text=[$('.heading h1')?.textContent,$('.heading>div>p')?.textContent,...Array.from(main?.querySelectorAll('.farmer-action h3,.farmer-action-copy>p')||[]).map(x=>x.textContent)].filter(Boolean).join('. ').replace(/\s+/g,' ').trim();if(!text){toast('There is no page text to read.');return}const u=new SpeechSynthesisUtterance(text);u.lang=voice?.lang||(lang==='mr'?'mr-IN':lang==='hi'?'hi-IN':'en-IN');if(voice)u.voice=voice;u.rate=.9;u.onerror=()=>toast('Read-aloud could not start. Check your device voice settings.');synth.cancel();synth.speak(u)}
document.addEventListener('pointerdown',e=>{const target=e.target.closest('.btn,.mobile-dock a,.nav a');if(!target||target.matches(':disabled'))return;target.classList.remove('tap-feedback');void target.offsetWidth;target.classList.add('tap-feedback');window.setTimeout(()=>target.classList.remove('tap-feedback'),420)});
// Keep deeper calculations available while the everyday farmer pages stay brief.
overview=function(){const p=plan.best,stage=stageLabel(state.stage),crops=FW.crops.map((c,i)=>p&&p.a[i]>.001?`<div class="overview-crop"><span><i class="crop-dot" style="background:${c.color}"></i>${c.name}</span><strong>${formatArea(p.a[i])}</strong></div>`:'').join('');let body=head('Overview','Today at a glance.',button('Update farm','edit',true,'settings'))+setupPrompt()+`<div class="overview-greeting"><span class="pill">${stage}</span><span>${formatArea(state.area)} · ${esc(state.region)}</span><a class="text-link" href="#journal">Log field update ${icon('arrow',13)}</a></div>`;if(!p)return body+noPlan();body+=`<div class="overview-metrics"><div class="overview-metric"><span>Estimated net return</span><strong>${money(p.mean)}</strong></div><div class="overview-metric"><span>Budget left</span><strong>${money(Math.max(0,state.budget-p.cost))}</strong></div><div class="overview-metric"><span>Water planned</span><strong>${num(p.water)} m³</strong></div></div><p class="overview-footnote">Planning estimate · check local prices before spending.</p><div class="grid overview-grid">${panel('Today','Your next checks.',actionList())}${panel('Weather','Live forecast unavailable',`<a class="btn weather-source" href="https://agromet.imd.gov.in/index.php/login/adv_status_index" target="_blank" rel="noopener">Check IMD forecast ${icon('arrow',13)}</a>`)}</div>`;if(crops)body+=panel('Crop plan','Suggested land by crop.',crops+'<a class="text-link" href="#planner">Review plan '+icon('arrow',13)+'</a>');return body};
actionList=function(){const items=dailyActions[state.stage]||dailyActions.before,today=localDateKey(),active=items.filter(a=>{const s=statusForAction(a.id);return !s||s.status==='pending'||(s.status==='snoozed'&&(s.until||'')<=today)}),resting=items.filter(a=>{const s=statusForAction(a.id);return s&&(s.status==='done'||s.status==='skipped'||(s.status==='snoozed'&&(s.until||'')>today))}),row=a=>`<article class="farmer-action"><span class="action-icon">${icon(a.ic,17)}</span><div class="farmer-action-copy"><h3>${a.title}</h3><p>${a.desc}</p><details class="action-context"><summary>Why / cost</summary><p>${a.why}</p><small>${a.cost}</small></details>${actionControls(a.id)}</div><button class="btn action-open" data-jump="${a.act}" aria-label="${esc(translateUI('Open '+a.title))}">${icon('arrow',15)}</button></article>`,shown=active.slice(0,2),more=active.slice(2).map(row).join(''),done=resting.map(a=>`<div class="resting-action"><span><strong>${a.title}</strong></span><button class="btn" data-restore-action="${a.id}">Show again</button></div>`).join('');return `<div class="today-action-list" id="today-actions"><div class="today-count"><strong>${active.length?`${active.length} checks`:'All checks done'}</strong><span>${stageLabel(state.stage)}</span></div>${shown.map(row).join('')}${more?`<details class="resting-list"><summary>More checks</summary>${more}</details>`:''}${!active.length?'<p class="compact-empty">Your checks are clear.</p>':''}${done?`<details class="resting-list"><summary>Done (${resting.length})</summary>${done}</details>`:''}</div>`};
farm=function(){const stage=stageLabel(state.stage);return head('My farm','The details used in your plan.',button('Edit farm details','edit',true,'settings'))+setupPrompt()+`<div class="grid equal">${panel(esc(state.name),esc(state.region),`<div class="metric-list"><div><span>Land</span><strong>${formatArea(state.area)}</strong></div><div><span>Crop stage</span><strong>${stage}</strong></div><div><span>Cash this season</span><strong>${money(state.budget)}</strong></div><div><span>Water this season</span><strong>${num(state.water)} m³</strong></div></div>`)}</div>`};
edit=function(){const d=$('#modal'),unit=state.areaUnit==='acre'?'acre':'ha',display=unit==='acre'?state.area*areaFactor:state.area;d.innerHTML=`<div class="modal-head"><h2>Set up your farm</h2><button class="close" data-act="close" aria-label="Close">×</button></div><p>Enter the basics for your plan.</p><form id="farm-form"><input type="hidden" name="name" value="${esc(state.name)}"><input type="hidden" name="soil" value="${esc(state.soil)}"><input type="hidden" name="evidence" value="${esc(state.evidence)}"><input type="hidden" name="risk" value="${state.risk}"><div class="form-grid"><div class="full"><label for="region">Village or district (optional)</label><input id="region" name="region" value="${esc(state.region)}" maxlength="80"></div><div class="full"><label for="area">Land area</label><div class="field-inline"><input id="area" name="area" type="number" min="0.1" max="${unit==='acre'?'49.42':'20'}" step="${unit==='acre'?'0.01':'0.1'}" data-unit="${unit}" value="${display.toFixed(2)}" required><select id="areaUnit" name="areaUnit"><option value="ha" ${unit==='ha'?'selected':''}>Hectares</option><option value="acre" ${unit==='acre'?'selected':''}>Acres</option></select></div></div><div><label for="budget">Season budget (₹)</label><input id="budget" name="budget" type="number" min="0" max="10000000" step="100" value="${state.budget}" required></div><div><label for="water">Available water (m³)</label><input id="water" name="water" type="number" min="0" max="500000" step="10" value="${state.water}" required></div><div class="full"><label for="stage">Current crop stage</label><select id="stage" name="stage">${stageCatalog.map(s=>`<option value="${s.id}" ${s.id===state.stage?'selected':''}>${s.label}</option>`).join('')}</select></div></div><div class="buttons" style="margin-top:20px;justify-content:flex-end"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn primary" type="submit">Save farm</button></div></form>`;applyLanguage(d);d.showModal()};
edit=function(){const d=$('#modal'),unit=state.areaUnit==='acre'?'acre':'ha',display=unit==='acre'?state.area*areaFactor:state.area;d.innerHTML=`<div class="modal-head"><h2>Set up your farm</h2><button class="close" data-act="close" aria-label="Close">×</button></div><p>Enter the basics for your plan.</p><form id="farm-form"><input type="hidden" name="name" value="${esc(state.name)}"><input type="hidden" name="soil" value="${esc(state.soil)}"><input type="hidden" name="evidence" value="${esc(state.evidence)}"><input type="hidden" name="risk" value="${state.risk}"><div class="form-grid"><div class="full"><label for="region">Village or district (optional)</label><input id="region" name="region" value="${esc(state.region)}" maxlength="80"></div><div class="full"><label for="area">Land area</label><div class="field-inline"><input id="area" name="area" type="number" min="0.1" max="${unit==='acre'?'49.42':'20'}" step="${unit==='acre'?'0.01':'0.1'}" data-unit="${unit}" value="${display.toFixed(2)}" required><select id="areaUnit" name="areaUnit"><option value="ha" ${unit==='ha'?'selected':''}>Hectares</option><option value="acre" ${unit==='acre'?'selected':''}>Acres</option></select></div></div><div><label for="budget">Season budget (₹)</label><input id="budget" name="budget" type="number" min="0" max="10000000" step="100" value="${state.budget}" required></div><div><label for="water">Available water (m³)</label><input id="water" name="water" type="number" min="0" max="500000" step="10" value="${state.water}" required></div><div class="full"><label for="stage">Current crop stage</label><select id="stage" name="stage">${stageCatalog.map(s=>`<option value="${s.id}" ${s.id===state.stage?'selected':''}>${s.label}</option>`).join('')}</select></div></div><div class="buttons" style="margin-top:20px;justify-content:flex-end"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn primary" type="submit">Save farm</button></div></form>`;applyLanguage(d);d.showModal()};
resources=function(){const p=plan.best;if(!p)return head('Water & budget','Plan crop water against what you have.',button('Edit farm','edit',false,'settings'))+noPlan();const rows=FW.crops.map((c,i)=>{const area=p.a[i],total=area*c.water,share=state.water?Math.min(100,total/state.water*100):0;if(area<=.001)return'';const econ=FW.cropEconomics(c,i,state),waterPerQ=(p.yields[i]||c.yield)*1000/Math.max(1,c.water);return'<article class="water-crop"><div class="water-crop-top"><strong><i class="crop-dot" style="background:'+c.color+'"></i>'+c.name+'</strong><span>'+formatArea(area)+' · '+c.days+' day example cycle</span></div><div class="water-crop-metrics"><div><small>Example need / ha</small><strong>'+num(c.water)+' m³</strong></div><div><small>Season water</small><strong>'+num(total)+' m³</strong><small>'+num(total*1000)+' L total</small></div><div><small>Water share</small><strong>'+share.toFixed(0)+'%</strong></div><div><small>Planned cost</small><strong>'+money(area*econ.cost)+'</strong><small>'+money(econ.cost)+' / ha</small></div><div><small>Example water productivity</small><strong>'+waterPerQ.toFixed(1)+' q / 1,000 m³</strong><small>Modeled yield ÷ assumed water</small></div></div><div class="bar water-bar"><span style="width:'+share+'%;background:'+c.color+'"></span></div><details class="plain-details"><summary>Simple planning split</summary><p>Plan watering around early growth, active growth, flowering or fruit formation, and harvest. Fieldwise does not calculate water timing by crop stage. Check local crop guidance and recent rain before irrigating.</p></details></article>'}).join('');return head('Water & budget','See how the crop plan uses your available water and working budget.',button('Edit farm','edit',false,'settings'))+'<div class="overview-metrics"><div class="overview-metric"><span>Available water</span><strong>'+num(state.water)+' m³</strong></div><div class="overview-metric"><span>Planned water</span><strong>'+num(p.water)+' m³</strong></div><div class="overview-metric"><span>Water buffer</span><strong>'+num(Math.max(0,state.water-p.water))+' m³</strong></div><div class="overview-metric"><span>Budget left</span><strong>'+money(Math.max(0,state.budget-p.cost))+'</strong></div></div>'+panel('Water and costs by crop','Example seasonal amounts; local quoted crop costs are used when entered.',rows||'<p>No crop mix selected yet.</p>')+'<section class="panel"><h2>Before you irrigate</h2><p>Check soil moisture and recent rain in the field. These estimates use sample crop water values; they do not read sensors or measure actual water. Effective rainfall and irrigation efficiency are not included.</p><p class="tiny">Water productivity is a demo ratio (modeled quintals per hectare ÷ assumed seasonal m³ per hectare). Cycle length and yield coefficients need local calibration. Use crop-stage advice from a local agronomist before deciding irrigation amounts.</p></section>'};
finance=function(){const p=plan.best,btn=button('Download PDF','export',false,'down');if(!p)return head('Money','A simple estimate for this season.',btn)+noPlan();const metrics=`<div class="overview-metrics"><div class="overview-metric"><span>Possible net return</span><strong>${money(p.mean)}</strong></div><div class="overview-metric"><span>Crop costs</span><strong>${money(p.cost)}</strong></div><div class="overview-metric"><span>Lower estimate</span><strong>${money(p.p10)}</strong></div></div>`;const budget=`<div class="metric-list"><div><span>Available</span><strong>${money(state.budget)}</strong></div><div><span>Planned crop costs</span><strong>${money(p.cost)}</strong></div><div><span>Left after planned costs</span><strong>${money(Math.max(0,state.budget-p.cost))}</strong></div></div>`;return head('Money','A simple estimate for this season.',btn)+metrics+panel('Season budget','',budget)+`<p class="notice">Planning estimate only. Check local prices and costs before spending.</p>`};
billing=function(){const due=bills.reduce((n,b)=>n+Math.max(0,Number(b.amount||0)-(b.payments||[]).reduce((x,p)=>x+Number(p.amount||0),0)),0),paid=bills.reduce((n,b)=>n+(b.payments||[]).reduce((x,p)=>x+Number(p.amount||0),0),0);const rows=bills.map(b=>{const paidBill=(b.payments||[]).reduce((n,p)=>n+Number(p.amount||0),0),left=Math.max(0,Number(b.amount)-paidBill);let action='Paid';if(left)action='<button class="btn" data-pay="'+esc(b.id)+'">Record payment</button>';return '<tr><td data-i18n-ignore>'+esc(b.supplier)+'</td><td>'+(b.dueDate||'—')+'</td><td>'+money(b.amount)+'</td><td>'+money(left)+'</td><td>'+action+'</td></tr>'}).join('');const body=rows?'<div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Due date</th><th>Amount</th><th>Left</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>':'<div class="empty"><p>Your bill book is empty.</p>'+button('Add first bill','billing-add',true,'plus')+'</div>';return head('Bills','Track bills and payments you have already made.',button('Export','billing-export',false,'down')+button('Add a bill','billing-add',true,'plus'))+'<div class="overview-metrics"><div class="overview-metric"><span>Still due</span><strong>'+money(due)+'</strong></div><div class="overview-metric"><span>Paid and recorded</span><strong>'+money(paid)+'</strong></div><div class="overview-metric"><span>Bills</span><strong>'+bills.length+'</strong></div></div>'+panel('Your bills','',body)+'<p class="notice">Record a payment after paying outside Fieldwise.</p>'};
planner=function(){const p=plan.best,actions=`<div class="tabs"><button data-preset="balanced" class="${tab==='balanced'?'active':''}">Balanced</button><button data-preset="return" class="${tab==='return'?'active':''}">Higher return</button><button data-preset="resilient" class="${tab==='resilient'?'active':''}">Lower risk</button></div>`,title=head('Crop plan','Choose a priority. The plan respects your land, budget and water.',button('Save plan','save',true,'plus'));if(!p)return title+actions+noPlan();const summary=`<div class="overview-metrics"><div class="overview-metric"><span>Planned cost</span><strong>${money(p.cost)}</strong></div><div class="overview-metric"><span>Water needed</span><strong>${num(p.water)} m³</strong></div><div class="overview-metric"><span>Possible net return</span><strong>${money(p.p10)}–${money(p.p90)}</strong></div></div><p class="notice">Estimate based on example crop values. Confirm local costs and prices.</p><details class="plain-details"><summary>Compare other choices</summary>${comparisonCards()}</details>`;return title+actions+panel('Suggested crop mix','Review before sowing.',allocation(p))+summary};
portfolio=function(){const rows=saved.map((s,i)=>`<div class="saved-row"><div><h3 data-i18n-ignore>${esc(s.name)}</h3><p>${formatSavedDate(s.date)} · ${formatArea(s.context.area,s.context.areaUnit||'ha')} · ${money(s.result.mean)}</p></div><div class="buttons"><button class="btn" data-load="${i}">Open</button><button class="btn" data-delete="${i}" aria-label="Delete ${esc(s.name)}">${icon('close',13)}</button></div></div>`).join(''),body=rows||`<div class="empty"><p>No saved plans yet.</p>${button('Save current plan','save',true,'plus')}</div>`;return head('Saved plans','Compare plans you have saved.',button('Save current plan','save',true,'plus'))+panel('Your plans',`${saved.length} saved`,body)};
journal=function(){const entries=Array.isArray(fieldLog)?fieldLog.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')):[],form=`<form id="journal-form"><input type="hidden" name="date" value="${localDateKey()}"><input type="hidden" name="stage" value="${state.stage}"><div class="form-grid"><div><label for="log-cost">Money spent (₹)</label><input id="log-cost" name="cost" type="number" min="0" step="1" inputmode="decimal" placeholder="Optional"></div><div><label for="log-water">Water used (m³)</label><input id="log-water" name="water" type="number" min="0" step="1" inputmode="decimal" placeholder="Optional"></div><div class="full"><details class="plain-details"><summary>Add harvest details</summary><div class="form-grid"><div><label for="log-yield">Harvest (quintals)</label><input id="log-yield" name="yieldQ" type="number" min="0" step="0.1" inputmode="decimal"></div><div><label for="log-price">Sale price (₹ / quintal)</label><input id="log-price" name="price" type="number" min="0" step="1" inputmode="decimal"></div></div></details></div><div class="full"><label for="log-note">Short note (optional)</label><textarea id="log-note" name="note" maxlength="300" rows="2" placeholder="What changed in the field?"></textarea></div></div><div class="buttons" style="margin-top:14px;justify-content:flex-end"><button class="btn primary" type="submit">Save update</button></div></form>`,rows=entries.map(x=>{const facts=(x.cost?`<span>${money(x.cost)} spent</span>`:'')+(x.water?`<span>${num(x.water)} m³ water</span>`:'')+(x.yieldQ?`<span>${Number(x.yieldQ).toFixed(1)} q harvested</span>`:''),note=x.note?`<p data-i18n-ignore>${esc(x.note)}</p>`:'';return`<article class="journal-entry"><div class="journal-entry-top"><strong>${formatSavedDate(x.date)} · ${stageLabel(x.stage)}</strong><button class="btn quiet" data-log-delete="${esc(x.id)}" aria-label="Delete field entry">${icon('close',13)}</button></div><div class="journal-facts">${facts}</div>${note}</article>`}).join('');return head('Field journal','Record real costs, water and harvest.',button('Download PDF','export',false,'down'))+panel('Add an update','Enter what you know today.',form)+panel('Recent updates','',rows||'<p>No updates yet.</p>')};
function render(){
 route=location.hash.slice(1)||'overview';if(route==='operator'&&!canManage){if(!accessChecked){$('#app').innerHTML=`<main class="access-check"><span class="brand-mark">${icon('leaf',23)}</span><h1>Checking account access</h1><p>Business tools open only for the verified owner account.</p></main>`;return}location.hash='overview';return}
 const visibleNavs=navs.filter(n=>n[0]!=='operator'||canManage);if(route==='billing'){location.hash='finance';return} if(!visibleNavs.some(n=>n[0]===route)&&!['portfolio','evidence'].includes(route)){location.hash='overview';return}
 const name=navs.find(n=>n[0]===route)?.[2]||({portfolio:'Saved plans',evidence:'About'}[route]||'Overview'),unitPrefs=[['en','English'],['mr','मराठी'],['hi','हिन्दी']],pages={overview,farm,profile,weather,billing,subscriptions,planner,resources,finance,evidence,portfolio,journal,operator};
 if(!pages[route]){location.hash='overview';return}
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#overview"><span class="brand-mark">${icon('leaf',23)}</span>fieldwise<span class="brand-dot">.</span></a><div class="nav-label">YOUR WORKSPACE</div><nav class="nav" aria-label="Farm workspace">${visibleNavs.map(([id,ic,label])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ic)}${label}</a>`).join('')}</nav><div class="side-bottom"><div class="field-note"><strong>${icon('leaf',14)} Rooted in better decisions.</strong><span>A little more clarity.<br>A more resilient season.</span><a href="#evidence">Our approach ${icon('arrow',12)}</a></div><div class="profile"><span class="avatar">FW</span><div><strong data-i18n-ignore>${esc(state.farmerName||state.name)}</strong><br><small data-i18n-ignore>${esc(state.region)}</small></div></div></div></aside><div class="main"><header class="topbar"><div class="breadcrumbs"><button class="mobile-menu" data-act="menu" aria-label="Open navigation">${icon('menu',20)}</button><span>Workspace</span><span>/</span><strong>${name}</strong></div><div class="top-right"><label class="language-wrap"><span class="sr-only">Language</span><select id="language-select" aria-label="Choose language" title="Choose the website language.">${unitPrefs.map(([id,label])=>`<option value="${id}" ${prefs.language===id?'selected':''}>${label}</option>`).join('')}</select></label><button class="btn utility-btn" data-act="font-size" aria-pressed="${!!prefs.largeText}" aria-label="Toggle larger text" title="Toggle larger text">A<span class="utility-plus">+</span></button><button class="btn utility-btn listen-btn" data-act="speak" aria-label="Read this page aloud" title="Read this page aloud">${icon('sound',16)}<span>Listen</span></button><button class="btn utility-btn sync-now" data-act="sync" title="Sync account records when signed in">Sync</button><span id="sync-status" class="badge amber" role="status" aria-live="polite">${currentSyncLabel}</span></div></header><main class="content"><div class="privacy-callout" id="privacy-hint" role="note">Public demo · changes stay on this device until a signed-in account syncs. Avoid sensitive entries on shared devices.</div>${pages[route]()}<footer class="footer"><span>${icon('leaf',12)} Fieldwise · Farm intelligence, grounded.</span><span>Example numbers · verify locally before spending</span></footer></main></div><nav class="mobile-dock" aria-label="Quick navigation">${[['overview','grid','Home'],['farm','field','Farm'],['planner','leaf','Plan'],['journal','book','Records'],['resources','water','Water']].map(([id,ic,label])=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(ic,18)}<span>${label}</span></a>`).join('')}</nav></div>`;
 document.body.classList.toggle('large-text',!!prefs.largeText);syncStatus(currentSyncLabel,currentSyncLabel.includes('Device')||currentSyncLabel.includes('Offline')||currentSyncLabel.includes('Local'));applyLanguage();
}
function syncStatus(label,offline=false){currentSyncLabel=label;const el=$('#sync-status');if(el){el.textContent=translateUI(label);el.className=offline?'badge amber':'badge';el.title=translateUI(offline?'Changes remain saved on this device. Cloud sync needs an online connection and sign-in.':'Farm records sync only to the signed-in account.')}const hint=$('#privacy-hint');if(hint){hint.textContent=translateUI(label.startsWith('Cloud')||label.startsWith('Saving')?'Cloud records are scoped to the signed-in account. Sign out before leaving a shared device.':'Public demo · changes stay in this browser until a signed-in account syncs. Avoid sensitive entries on shared devices.')}}
function updateActionStatus(id,status){actionStates={...actionStates};if(status==='restore')delete actionStates[id];else if(status==='done')actionStates[id]={status:'done',at:localDateKey()};else if(status==='skip')actionStates[id]={status:'skipped',at:localDateKey()};else if(status==='snooze'){const d=new Date();d.setDate(d.getDate()+1);actionStates[id]={status:'snoozed',until:localDateKey(d)}}persist('fw-action-status',actionStates);render()}
function announcePage(){if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){toast('Read-aloud is not available in this browser.');return}if(window.speechSynthesis.speaking){window.speechSynthesis.cancel();return}const parts=[$('.heading h1')?.textContent,$('.heading>div>p')?.textContent,$('#today-actions')?.innerText,$('#journal-form')?.innerText].filter(Boolean),text=parts.join('. ').replace(/\s+/g,' ').trim();if(!text){toast('There is no page text to read.');return}const u=new SpeechSynthesisUtterance(text),lang=prefs.language||'en';u.lang=lang==='mr'?'mr-IN':lang==='hi'?'hi-IN':'en-IN';u.rate=.9;window.speechSynthesis.cancel();window.speechSynthesis.speak(u)}
