function translateUI(value){const lang=prefs?.language||'en';return window.FIELDWISE_I18N?window.FIELDWISE_I18N.translate(String(value??''),lang,localeDictionaries[lang]):String(value??'')}
function applyLanguage(target){const lang=prefs?.language||'en';document.documentElement.lang=lang==='mr'?'mr-IN':lang==='hi'?'hi-IN':'en-IN';document.title=translateUI('Fieldwise — Farm decision intelligence');const meta=document.querySelector('meta[name=description]');if(meta)meta.content=translateUI('Fieldwise helps smallholder farmers compare crop plans, water use, costs and uncertainty using transparent local context.');const roots=target?[target]:[$('#app'),$('#modal'),$('#toast')].filter(Boolean);for(const root of roots){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(node.parentElement?.closest('[data-i18n-ignore]'))continue;node.nodeValue=translateUI(node.nodeValue)}for(const el of root.querySelectorAll('[placeholder],[title],[aria-label],[alt]')){if(el.closest('[data-i18n-ignore]'))continue;for(const attr of ['placeholder','title','aria-label','alt']){const value=el.getAttribute(attr);if(value)el.setAttribute(attr,translateUI(value))}}for(const el of root.querySelectorAll('input[type=button],input[type=submit]'))if(el.value)el.value=translateUI(el.value)}}
function planner(){const p=plan.best;return head('Compare plans','Choose what matters most. Each mix stays within the land, cash and water limits you entered.',button('Save this plan','save',true,'plus'))+`<div class="tabs"><button data-preset="balanced" class="${tab==='balanced'?'active':''}">Balanced</button><button data-preset="return" class="${tab==='return'?'active':''}">Prioritize income</button><button data-preset="resilient" class="${tab==='resilient'?'active':''}">Protect what you can</button></div>${!p?noPlan():`<div class="grid"><div>${featuredPanel('Suggested crop mix',`${stageLabel(state.stage)} · use for next-season planning if crops are already planted`,allocation(p))}<div class="evidence-card"><span class="badge amber">Example values · check locally</span><p>This mix fits the limits you entered and matches your selected priority. The crop yield, price and cost values are not locally verified.</p></div></div>${panel('What does this choice mean?','A simple summary of the trade-off.',`<div class="metric-list"><div><span>Planned crop spending</span><strong>${money(p.cost)} of ${money(state.budget)}</strong></div><div><span>Water needed</span><strong>${num(p.water)} of ${num(state.water)} m³</strong></div><div><span>Possible amount after crop costs</span><strong>${money(p.p10)} to ${money(p.p90)}</strong></div><div><span>Lower example result</span><strong>${money(p.tail)}</strong></div></div><details class="plain-details"><summary>How the estimate was made</summary><p>The average and range come from 240 repeatable computer simulations using made-up demonstration crop values. These numbers are not a real-world probability or a promise of profit. Household costs, rent, debt, pests and long-term soil effects are not included.</p></details>`)}</div>${panel('Three ways to use the same limits','Pick the outcome that matters most to you.',comparisonCards())}<div class="grid equal">${panel('Steps through the season','Choose your current stage in My farm. These checks are reminders, not automatic field readings.',seasonTimeline())}${panel('Example crop values','Illustrative values used by this demo; they are not local advice.',`<details class="plain-details"><summary>View values used in the calculation</summary><div class="table-wrap"><table><thead><tr><th>CROP</th><th>AREA</th><th>YIELD / HA</th><th>PRICE / QUINTAL</th><th>COST / HA</th><th>WATER / HA</th></tr></thead><tbody>${FW.crops.map((c,i)=>`<tr><td>${c.name}</td><td>${formatArea(p.a[i])}</td><td>${c.yield} q</td><td>${money(c.price)}</td><td>${money(c.cost)}</td><td>${num(c.water)} m³</td></tr>`).join('')}</tbody></table></div><p class="timeline-note">Check actual local quotations and agronomic advice before buying or changing a crop.</p></details>`)}</div>`}`}

document.addEventListener('click',e=>{
 const status=e.target.closest('[data-action-status]');if(status){updateActionStatus(status.dataset.actionStatus,status.dataset.status);return}
 const restore=e.target.closest('[data-restore-action]');if(restore){updateActionStatus(restore.dataset.restoreAction,'restore');return}
 const jump=e.target.closest('[data-jump]');if(jump){const act=jump.dataset.jump;if(act==='journal')location.hash='journal';else if(act==='billing')location.hash='billing';else if(act==='cost')location.hash='finance';else if(act==='soil')edit();else if(act==='risk')location.hash='finance';return}
 const del=e.target.closest('[data-log-delete]');if(del){if(window.confirm(translateUI('Delete this field entry?'))){fieldLog=fieldLog.filter(x=>x.id!==del.dataset.logDelete);persist('fw-field-log',fieldLog);render();toast('Field entry deleted.')}return}
 const b=e.target.closest('[data-act]');if(!b)return;
 if(b.dataset.act==='font-size'){prefs.largeText=!prefs.largeText;try{localStorage.setItem('fw-prefs',JSON.stringify(prefs))}catch{}document.body.classList.toggle('large-text',!!prefs.largeText);b.setAttribute('aria-pressed',String(!!prefs.largeText));toast(prefs.largeText?'Larger text enabled.':'Standard text size restored.');return}
 if(b.dataset.act==='speak'){speakPage();return}
 if(b.dataset.act==='sync'){if(!navigator.onLine){syncStatus('Offline · changes stay on this device',true);toast('You are offline. Your entries remain on this device.');return}syncBackend();return}
});
document.addEventListener('submit',e=>{
 const form=e.target;if(!form||!form.id)return;
 if(form.id==='farm-form'){e.preventDefault();const fd=new FormData(form),areaHa=Number(form.elements.area.value);state={...state,name:String(fd.get('name')).trim(),region:String(fd.get('region')).trim(),area:areaHa,areaUnit:String(fd.get('areaUnit')),budget:Number(fd.get('budget')),water:Number(fd.get('water')),soil:String(fd.get('soil')),evidence:String(fd.get('evidence')),risk:Number(fd.get('risk')),stage:String(fd.get('stage')),profileComplete:true};plan=FW.optimize(state);persist('fw-context',state);$('#modal').close();render();toast('Farm details saved. Your estimates have been updated.');return}
 if(form.id==='save-form'){e.preventDefault();if(!plan.best){toast('There is no feasible plan to save yet.');return}const name=String(new FormData(form).get('planName')||'').trim();saved=[...saved,{name:name||`Season plan ${saved.length+1}`,date:localDateKey(),context:{...state},result:{mean:plan.best.mean,p10:plan.best.p10,p90:plan.best.p90},a:[...plan.best.a]}];persist('fw-plans',saved);$('#modal').close();render();toast('Plan saved to your farm portfolio.');return}
 if(form.id==='bill-form'){e.preventDefault();const fd=new FormData(form),amount=Number(fd.get('amount'));if(!(amount>0)){toast('Enter a bill amount greater than zero.');return}bills=[...bills,{id:`B-${Date.now().toString().slice(-7)}`,supplier:String(fd.get('supplier')).trim(),category:String(fd.get('category')),amount,dueDate:String(fd.get('dueDate')),payments:[]}];persist('fw-bills',bills);$('#modal').close();render();toast('Bill added to your bill book.');return}
 if(form.id==='payment-form'){e.preventDefault();const fd=new FormData(form),b=bills.find(x=>x.id===String(fd.get('billId'))),amount=Number(fd.get('amount'));if(!b){toast('Bill not found.');return}const paid=(b.payments||[]).reduce((n,x)=>n+Number(x.amount||0),0),remaining=Math.max(0,Number(b.amount)-paid);if(!(amount>0)||amount>remaining){toast('Enter an amount within the remaining balance.');return}b.payments=[...(b.payments||[]),{amount,date:String(fd.get('date')),method:String(fd.get('method')),reference:String(fd.get('reference')||'').trim()}];persist('fw-bills',bills);$('#modal').close();render();toast('Payment record saved. No money moved in Fieldwise.');return}
 if(form.id==='journal-form'){e.preventDefault();const fd=new FormData(form),entry={id:`L-${Date.now().toString(36)}`,date:String(fd.get('date')),stage:String(fd.get('stage')),cost:Number(fd.get('cost')||0),water:Number(fd.get('water')||0),yieldQ:Number(fd.get('yieldQ')||0),price:Number(fd.get('price')||0),note:String(fd.get('note')||'').trim()};if(!entry.cost&&!entry.water&&!entry.yieldQ&&!entry.note){toast('Add a measured amount or a short field note first.');return}fieldLog=[entry,...fieldLog];state={...state,fieldObservationCount:fieldLog.length};plan=FW.optimize(state);persist('fw-field-log',fieldLog);persist('fw-context',state);form.reset();form.elements.date.value=localDateKey();form.elements.stage.value=state.stage;render();toast('Field update saved.');return}
});
document.addEventListener('change',e=>{
 if(e.target.id==='language-select'){prefs.language=e.target.value;try{localStorage.setItem('fw-prefs',JSON.stringify(prefs))}catch{}render();return}
 if(e.target.dataset.task){const id=e.target.dataset.task;tasks=e.target.checked?[...new Set([...tasks,id])]:tasks.filter(x=>x!==id);persist('fw-tasks',tasks);const row=e.target.closest('.season-stage');if(row)row.classList.toggle('is-done',e.target.checked);return}
});
window.addEventListener('hashchange',()=>{if($('.sidebar'))$('.sidebar').classList.remove('open');render()});
window.addEventListener('offline',()=>syncStatus('Offline · changes stay on this device',true));
window.addEventListener('online',()=>{syncStatus('Back online · syncing…',true);syncBackend()});
render();syncBackend();

// Farmer-first pass: keep the daily workspace short and make secondary records easy to find.
navs.splice(0,navs.length,
 ['overview','grid','Overview'],['farm','field','My farm'],['profile','brief','Farmer profile'],['planner','leaf','Crop plan'],
 ['resources','water','Water & budget'],['weather','cloud','Weather'],['finance','wallet','Money & bills'],['journal','book','Records'],['subscriptions','brief','Plans']
);
overview=function(){
 const p=plan.best, crops=FW.crops.map((c,i)=>p&&p.a[i]>.001?`<div class="overview-crop"><span><i class="crop-dot" style="background:${c.color}"></i>${c.name}</span><strong>${formatArea(p.a[i])}</strong></div>`:'').join('');
 let out=head('Overview','Your farm, in one quick view.',button('Edit farm','edit',true,'settings'));
 if(!p)return out+setupPrompt()+noPlan();
 out+=`<div class="overview-greeting"><span class="pill">${stageLabel(state.stage)}</span><span>${formatArea(state.area)}</span><a class="text-link" href="#journal">Add a field update ${icon('arrow',13)}</a></div>
 <div class="overview-metrics"><div class="overview-metric"><span>Possible return</span><strong>${money(p.mean)}</strong></div><div class="overview-metric"><span>Budget left</span><strong>${money(Math.max(0,state.budget-p.cost))}</strong></div><div class="overview-metric"><span>Water planned</span><strong>${num(p.water)} m³</strong></div></div>
 <p class="overview-footnote">Example estimate · check local prices before spending.</p><div class="grid overview-grid">${panel('Today','Two quick checks.',actionList())}${panel('Weather','See your local five-day forecast.',`<a class="btn weather-source" href="#weather">Open forecast ${icon('arrow',13)}</a>`)}</div>
 ${crops?panel('Suggested crop mix','For next season if crops are already planted.',crops+`<a class="text-link" href="#planner">Review crop plan ${icon('arrow',13)}</a>`):''}
 <div class="overview-shortcuts"><a href="#billing">Bills ${icon('arrow',13)}</a><a href="#portfolio">Saved plans ${icon('arrow',13)}</a></div>`;
 return out;
};
actionList=function(){
 const items=dailyActions[state.stage]||dailyActions.before,today=localDateKey(),active=items.filter(a=>{const s=statusForAction(a.id);return !s||s.status==='pending'||(s.status==='snoozed'&&(s.until||'')<=today)}),shown=active.slice(0,2);
 if(!shown.length)return '<p class="compact-empty">You are all caught up.</p>';
 return `<div class="today-action-list">${shown.map(a=>`<div class="simple-check"><span>${icon(a.ic,16)}</span><strong>${a.title}</strong><button class="btn quiet" data-action-status="${a.id}" data-status="done" aria-label="Mark done">Done</button></div>`).join('')}${active.length>2?`<details class="plain-details"><summary>${active.length-2} more checks</summary>${active.slice(2).map(a=>`<div class="simple-check"><span>${icon(a.ic,16)}</span><strong>${a.title}</strong><button class="btn quiet" data-action-status="${a.id}" data-status="done">Done</button></div>`).join('')}</details>`:''}</div>`;
};
farm=function(){const stage=stageLabel(state.stage);return head('My farm','Only the details used in your plan.',button('Edit farm','edit',true,'settings'))+`<section class="panel"><div class="farm-summary"><div><h2>${esc(state.name)}</h2><p>${esc(state.region||'Farm profile')} · ${stage}</p></div><span class="pill">${formatArea(state.area)}</span></div><div class="overview-metrics"><div class="overview-metric"><span>Season budget</span><strong>${money(state.budget)}</strong></div><div class="overview-metric"><span>Available water</span><strong>${num(state.water)} m³</strong></div></div></section><p class="tiny">Crop prices and yields are examples. Soil details are not verified.</p>`};
edit=function(){const d=$('#modal'),unit=state.areaUnit==='acre'?'acre':'ha',display=unit==='acre'?state.area*areaFactor:state.area;d.innerHTML=`<div class="modal-head"><h2>Farm details</h2><button class="close" data-act="close" aria-label="Close">×</button></div><p>Enter what you know. You can change it later.</p><form id="farm-form"><input type="hidden" name="name" value="${esc(state.name)}"><input type="hidden" name="region" value="${esc(state.region)}"><input type="hidden" name="soil" value="${esc(state.soil)}"><input type="hidden" name="evidence" value="${esc(state.evidence)}"><input type="hidden" name="risk" value="${state.risk}"><div class="form-grid"><div class="full"><label for="area">Land area</label><div class="field-inline"><input id="area" name="area" type="number" min="0.1" max="${unit==='acre'?'49.42':'20'}" step="${unit==='acre'?'0.01':'0.1'}" data-unit="${unit}" value="${display.toFixed(2)}" required><select id="areaUnit" name="areaUnit"><option value="ha" ${unit==='ha'?'selected':''}>Hectares</option><option value="acre" ${unit==='acre'?'selected':''}>Acres</option></select></div></div><div><label for="budget">Season budget (₹)</label><input id="budget" name="budget" type="number" min="0" max="10000000" step="100" value="${state.budget}" required></div><div><label for="water">Water available (m³)</label><input id="water" name="water" type="number" min="0" max="500000" step="10" value="${state.water}" required></div><div class="full"><label for="stage">Crop stage</label><select id="stage" name="stage">${stageCatalog.map(s=>`<option value="${s.id}" ${s.id===state.stage?'selected':''}>${s.label}</option>`).join('')}</select></div></div><div class="buttons" style="margin-top:16px;justify-content:flex-end"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn primary" type="submit">Save details</button></div></form>`;applyLanguage(d);d.showModal()};
resources=function(){const p=plan.best;if(!p)return head('Water','Your available water and plan.',button('Edit farm','edit',false,'settings'))+noPlan();const rows=FW.crops.map((c,i)=>p.a[i]>.001?`<div class="bar-row"><span>${c.name}</span><div class="bar"><span style="width:${Math.min(100,p.a[i]*c.water/Math.max(1,state.water)*100)}%;background:${c.color}"></span></div><strong>${num(p.a[i]*c.water)} m³</strong></div>`:'').join('');return head('Water','Planned use against your limit.',button('Edit farm','edit',false,'settings'))+`<div class="overview-metrics"><div class="overview-metric"><span>Available</span><strong>${num(state.water)} m³</strong></div><div class="overview-metric"><span>Planned</span><strong>${num(p.water)} m³</strong></div><div class="overview-metric"><span>Left</span><strong>${num(Math.max(0,state.water-p.water))} m³</strong></div></div>`+panel('Use by crop','Example water needs.',rows)+`<p class="tiny">Confirm irrigation needs with local field conditions.</p>`};
finance=function(){const p=plan.best;if(!p)return head('Money','A simple season estimate.',button('Download PDF','export',false,'down'))+noPlan();return head('Money','Check the budget before spending.',button('Download PDF','export',false,'down'))+`<div class="overview-metrics"><div class="overview-metric"><span>Possible return</span><strong>${money(p.mean)}</strong></div><div class="overview-metric"><span>Crop costs</span><strong>${money(p.cost)}</strong></div><div class="overview-metric"><span>Budget left</span><strong>${money(Math.max(0,state.budget-p.cost))}</strong></div><div class="overview-metric"><span>Lower example</span><strong>${money(p.p10)}</strong></div></div><details class="plain-details"><summary>How to read these amounts</summary><p>Example crop values only. This is not a guaranteed profit; household costs, debt and local prices are not included.</p></details><a class="btn" href="#billing">Open bill book ${icon('arrow',13)}</a>`};
planner=function(){const p=plan.best,title=head('Crop plan','Choose what matters most this season.',button('Save plan','save',true,'plus')),tabs=`<div class="tabs"><button data-preset="balanced" class="${tab==='balanced'?'active':''}">Balanced</button><button data-preset="return" class="${tab==='return'?'active':''}">More income</button><button data-preset="resilient" class="${tab==='resilient'?'active':''}">Lower risk</button></div>`;if(!p)return title+tabs+noPlan();return title+tabs+panel('Suggested mix','Review before sowing.',allocation(p))+`<div class="overview-metrics"><div class="overview-metric"><span>Cost</span><strong>${money(p.cost)}</strong></div><div class="overview-metric"><span>Water</span><strong>${num(p.water)} m³</strong></div><div class="overview-metric"><span>Possible return range</span><strong>${money(p.p10)}–${money(p.p90)}</strong></div></div><p class="tiny">Planning example only. Check local prices and advice.</p><details class="plain-details"><summary>Compare other choices</summary>${comparisonCards()}</details><a class="btn" href="#portfolio">See saved plans ${icon('arrow',13)}</a>`};
subscriptions=function(){return head('Plans','The basic tools are free. Paid features are not available yet.')+`<div class="subscription-grid"><article class="plan-card"><span class="pill">FREE</span><h2>Fieldwise Basic</h2><div class="plan-price">₹0</div><ul><li>Crop plan, water and budget</li><li>Field notes and bill book</li><li>PDF and offline records</li></ul></article><article class="plan-card plan-card-plus"><span class="pill">PLANNED</span><h2>Fieldwise Plus</h2><ul><li>Local weather and market alerts</li><li>Season reminders and family plots</li><li>Optional adviser support</li></ul><p class="tiny">Only after these services are verified and ready.</p></article></div><p class="notice subscription-note">No paid plan or payment is active. Use Fieldwise Basic without paying.</p>`};
portfolio=function(){const rows=saved.map((s,i)=>`<div class="saved-row"><div><h3 data-i18n-ignore>${esc(s.name)}</h3><p>${formatSavedDate(s.date)} · ${formatArea(s.context.area,s.context.areaUnit||'ha')} · ${money(s.result.mean)}</p></div><div class="buttons"><button class="btn" data-load="${i}">Open</button><button class="btn quiet" data-delete="${i}" aria-label="Delete ${esc(s.name)}">×</button></div></div>`).join('');return head('Saved plans','Keep a plan to compare later.',button('Save current plan','save',true,'plus'))+panel('Your plans',`${saved.length} saved`,rows||`<div class="empty"><p>No saved plans yet.</p><a class="btn" href="#planner">Make a crop plan</a></div>`)};
// Keep payment records focused on bills already paid or due.
billing=function(){const due=bills.reduce((n,b)=>n+Math.max(0,Number(b.amount||0)-(b.payments||[]).reduce((x,p)=>x+Number(p.amount||0),0)),0),paid=bills.reduce((n,b)=>n+(b.payments||[]).reduce((x,p)=>x+Number(p.amount||0),0),0),rows=bills.map(b=>{const paidBill=(b.payments||[]).reduce((n,p)=>n+Number(p.amount||0),0),left=Math.max(0,Number(b.amount)-paidBill);return`<article class="simple-bill"><div><strong>${esc(b.supplier||'Farm bill')}</strong><small>${b.dueDate||'No due date'}</small></div><strong>${money(left)} <small>${left?'left':'paid'}</small></strong>${left?`<button class="btn" data-pay="${esc(b.id)}">Record payment</button>`:'<span class="pill">Paid</span>'}</article>`}).join('');return head('Bills','Record farm bills and payments.',button('Add bill','billing-add',true,'plus'))+`<div class="overview-metrics"><div class="overview-metric"><span>Still due</span><strong>${money(due)}</strong></div><div class="overview-metric"><span>Paid</span><strong>${money(paid)}</strong></div></div>${panel('Bill book',`${bills.length} bills`,rows||`<div class="empty"><p>No bills yet.</p><button class="btn primary" data-act="billing-add">Add your first bill</button></div>`)}<p class="tiny">Record payments made outside Fieldwise. This app does not move money.</p>`};
journal=function(){const entries=Array.isArray(fieldLog)?fieldLog.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')):[],form=`<form id="journal-form"><input type="hidden" name="date" value="${localDateKey()}"><input type="hidden" name="stage" value="${state.stage}"><div class="form-grid"><div><label for="log-cost">Money spent (₹)</label><input id="log-cost" name="cost" type="number" min="0" step="1" placeholder="Optional"></div><div><label for="log-water">Water used (m³)</label><input id="log-water" name="water" type="number" min="0" step="1" placeholder="Optional"></div><div class="full"><details class="plain-details"><summary>Add harvest details</summary><div class="form-grid"><div><label for="log-yield">Harvest (quintals)</label><input id="log-yield" name="yieldQ" type="number" min="0" step="0.1"></div><div><label for="log-price">Sale price (₹/quintal)</label><input id="log-price" name="price" type="number" min="0" step="1"></div></div></details></div><div class="full"><label for="log-note">Short note</label><textarea id="log-note" name="note" maxlength="300" rows="2" placeholder="Optional"></textarea></div></div><button class="btn primary" style="margin-top:14px" type="submit">Save update</button></form>`,rows=entries.map(x=>`<article class="journal-entry"><div class="journal-entry-top"><strong>${formatSavedDate(x.date)} · ${stageLabel(x.stage)}</strong><button class="btn quiet" data-log-delete="${esc(x.id)}" aria-label="Delete field entry">×</button></div><div class="journal-facts">${x.cost?`<span>${money(x.cost)} spent</span>`:''}${x.water?`<span>${num(x.water)} m³ water</span>`:''}${x.yieldQ?`<span>${Number(x.yieldQ).toFixed(1)} q harvested</span>`:''}</div>${x.note?`<p data-i18n-ignore>${esc(x.note)}</p>`:''}</article>`).join('');return head('Records','Keep field updates and farm bills together.',`<a class="btn" href="#billing">Bill book ${icon('arrow',13)}</a>`)+panel('Field update','Add what you know today.',form)+panel('Recent updates','',rows||'<p>No field updates yet.</p>')};
