Object.assign(localeDictionaries.hi,{'Overview':'अवलोकन','My farm':'मेरा खेत','Crop plan':'फसल योजना','Water':'पानी','Money':'पैसा','Records':'रिकॉर्ड','Plans':'योजनाएँ','Your farm, in one quick view.':'आपके खेत की एक नज़र में जानकारी।','Possible return':'संभावित कमाई','Budget left':'बचा हुआ बजट','Water planned':'योजनाबद्ध पानी','Suggested crop mix':'सुझाया गया फसल मिश्रण','Check before field work.':'खेत का काम करने से पहले जाँचें।','Open local forecast':'स्थानीय मौसम देखें','The basic tools are free. Paid features are not available yet.':'ज़रूरी सुविधाएँ मुफ़्त हैं। भुगतान वाली सुविधाएँ अभी उपलब्ध नहीं हैं।','Fieldwise Basic':'फील्डवाइज़ बेसिक','Fieldwise Plus':'फील्डवाइज़ प्लस','No paid plan or payment is active. Use Fieldwise Basic without paying.':'कोई भुगतान योजना शुरू नहीं है। फील्डवाइज़ बेसिक मुफ़्त इस्तेमाल करें।','Farm details':'खेत की जानकारी','Enter what you know. You can change it later.':'जो जानकारी मालूम है, भरें। बाद में बदल सकते हैं।','Season budget (₹)':'मौसम का बजट (₹)','Water available (m³)':'उपलब्ध पानी (m³)','Crop stage':'फसल की अवस्था','Save details':'जानकारी सेव करें','Saved plans':'सेव की गई योजनाएँ','Bills':'बिल','Bill book':'बिल बुक','Still due':'बाकी भुगतान','Add bill':'बिल जोड़ें','Money spent (₹)':'खर्च (₹)','Water used (m³)':'इस्तेमाल हुआ पानी (m³)','Save update':'अपडेट सेव करें'});

// Farmer profile, live forecast, combined money and bills, expanded crop-water view.
let weatherData=null,weatherBusy=false,weatherError='';
profile=function(){const opts=FW.crops.map(c=>'<option '+((state.primaryCrop||'')===c.name?'selected':'')+'>'+esc(c.name)+'</option>').join('');return head('Farmer profile','Your name, village and main crop.','')+'<form id="profile-form" class="panel profile-form"><div class="form-grid"><div><label for="farmer-name">Farmer name</label><input id="farmer-name" name="farmerName" maxlength="60" value="'+esc(state.farmerName||'')+'" placeholder="Your name"></div><div><label for="profile-crop">Main crop</label><select id="profile-crop" name="primaryCrop"><option value="">Choose crop</option>'+opts+'</select></div><div class="full"><label for="profile-location">Village or district</label><input id="profile-location" name="region" maxlength="100" value="'+esc(state.region||'')+'" placeholder="e.g. Pune district, Maharashtra"><small>Use a village or district only. Do not enter your full address.</small></div></div><div class="buttons" style="margin-top:16px"><button class="btn primary" type="submit">Save profile</button><a class="btn" href="#farm">Farm details</a></div></form><section class="panel"><h2>Farm at a glance</h2><div class="overview-metrics"><div class="overview-metric"><span>Plot</span><strong>'+esc(state.name)+'</strong></div><div class="overview-metric"><span>Area</span><strong>'+formatArea(state.area)+'</strong></div><div class="overview-metric"><span>Crop stage</span><strong>'+stageLabel(state.stage)+'</strong></div></div></section><p class="tiny">Your profile is saved with this farm on this device. Signed-in sync uses your account; the public demo is device-only.</p>'};
function localEconomicsPanel(){const rows=FW.crops.map((c,i)=>{const e=FW.cropEconomics(c,i,state);return`<tr><td>${c.name}</td><td><label class="sr-only" for="local-price-${i}">${c.name} selling price per quintal</label><input id="local-price-${i}" name="price-${i}" type="number" min="0.01" step="1" value="${e.price}" required></td><td><label class="sr-only" for="local-cost-${i}">${c.name} cultivation cost per hectare</label><input id="local-cost-${i}" name="cost-${i}" type="number" min="0.01" step="100" value="${e.cost}" required></td><td>${state.cropEconomics?.[c.name]?'Farmer entered':'Example'}</td></tr>`}).join(''),source=state.economicsSource?`${esc(state.economicsSource)} · ${esc(state.economicsDate||'date not entered')}`:'Example values are still in use.';return panel('Local prices and costs','Enter a dated local quote or market observation. Saving it recalculates crop plans and stress tests.',`<form id="economics-form"><div class="table-wrap"><table><thead><tr><th>CROP</th><th>SELLING PRICE / QUINTAL (₹)</th><th>CULTIVATION COST / HA (₹)</th><th>INPUT STATUS</th></tr></thead><tbody>${rows}</tbody></table></div><div class="form-grid"><div><label for="economics-source">Where did you get the quote?</label><select id="economics-source" name="source" required><option value="">Choose a source</option>${['Local mandi / e-NAM','Supplier quote','FPO or cooperative','Other local source'].map(x=>`<option ${state.economicsSource===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label for="economics-date">Quote date</label><input id="economics-date" name="date" type="date" value="${esc(state.economicsDate||localDateKey())}" required></div></div><div class="buttons" style="margin-top:14px"><button class="btn primary" type="submit">Use these local inputs</button><a class="btn" href="https://www.enam.gov.in/web/dashboard/live_price" target="_blank" rel="noopener">Check e-NAM prices ↗</a></div></form><p class="tiny">Current source: ${source}. Fieldwise does not scrape or auto-import market data. Match the crop variety and grade; include transport, fees and losses in your figures.</p>`)}
function weatherText(code){if(code===0)return'Sunny';if([1,2,3].includes(code))return'Partly cloudy';if([45,48].includes(code))return'Fog';if([51,53,55,56,57].includes(code))return'Drizzle';if([61,63,65,66,67,80,81,82].includes(code))return'Rain';if([71,73,75,77,85,86].includes(code))return'Snow';if([95,96,99].includes(code))return'Thunderstorm';return'Weather'}
async function loadWeather(){if(weatherBusy)return;const place=String(state.region||'').split('·')[0].trim();if(!place||!state.profileComplete||/demo context/i.test(state.region||'')){weatherError='Enter your actual village or district in Farmer profile first.';render();return}weatherBusy=true;weatherError='';render();try{const q=new URLSearchParams({name:place,count:'1',language:'en',format:'json'}),g=await fetch('https://geocoding-api.open-meteo.com/v1/search?'+q,{cache:'no-store'});if(!g.ok)throw new Error('Location lookup unavailable');const geo=await g.json(),loc=geo.results&&geo.results[0];if(!loc)throw new Error('No matching place found. Check the village or district name.');const params=new URLSearchParams({latitude:String(loc.latitude),longitude:String(loc.longitude),current:'temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,weather_code,wind_speed_10m,wind_gusts_10m',hourly:'temperature_2m,precipitation_probability,precipitation,wind_speed_10m,wind_gusts_10m,et0_fao_evapotranspiration',daily:'weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,precipitation_sum,precipitation_hours,wind_speed_10m_max,wind_gusts_10m_max,et0_fao_evapotranspiration,uv_index_max,sunrise,sunset',timezone:'auto',forecast_days:'5',forecast_hours:'24'}),r=await fetch('https://api.open-meteo.com/v1/forecast?'+params,{cache:'no-store'});if(!r.ok)throw new Error('Forecast service unavailable');const data=await r.json();if(!data.current||!data.daily||!data.daily.time.length)throw new Error('Forecast not available for this place.');weatherData={data:data,place:loc.name+(loc.admin1?', '+loc.admin1:''),fetchedAt:new Date().toISOString()};state={...state,weatherFetchedAt:weatherData.fetchedAt};plan=FW.optimize(state);persist('fw-context',state)}catch(e){weatherError=e.message||'Could not load forecast. Check your connection and try again.'}finally{weatherBusy=false;render()}}
weather=function(){
 const action=button(weatherBusy?'Loading…':'Refresh forecast','weather-refresh',true,'sun');
 const title=head('Weather forecast','Hourly field view and five-day outlook for your village or district.',action);
 if(!weatherData){return title+`<section class="panel weather-empty"><h2>${weatherBusy?'Getting local forecast…':'Check the forecast near your farm'}</h2><p>${weatherError?esc(weatherError):'A district-level forecast can help you plan field work.'}</p><button class="btn primary" data-act="weather-load" ${weatherBusy?'disabled':''}>${weatherBusy?'Loading…':'Load local forecast'}</button><p class="tiny">Uses the village or district in Farmer profile. No GPS is used. Verify warnings with IMD.</p><a href="https://agromet.imd.gov.in/index.php/login/adv_status_index" target="_blank" rel="noopener">IMD farm advisories ↗</a></section>`;}
 const d=weatherData.data,c=d.current,days=d.daily,h=d.hourly||{};
 const fmtDate=x=>new Date(x+'T12:00:00').toLocaleDateString(localeForUI(),{weekday:'short',day:'numeric',month:'short'});
 const fmtTime=x=>x?new Date(x).toLocaleTimeString(localeForUI(),{hour:'numeric',minute:'2-digit'}):'—';
 const cards=days.time.map((date,i)=>`<article class="forecast-day"><span>${fmtDate(date)}</span><strong>${Math.round(days.temperature_2m_max[i])}° / ${Math.round(days.temperature_2m_min[i])}°</strong><span>${weatherText(days.weather_code[i])}</span><small>Rain ${days.precipitation_probability_max[i]??'—'}% · ${Number(days.precipitation_sum[i]||0).toFixed(1)} mm · wind ${Math.round(days.wind_speed_10m_max?.[i]||0)} km/h</small><details class="plain-details"><summary>More for this day</summary><small>Rain hours ${days.precipitation_hours?.[i]??'—'} · gusts ${Math.round(days.wind_gusts_10m_max?.[i]||0)} km/h · ET₀ ${Number(days.et0_fao_evapotranspiration?.[i]||0).toFixed(1)} mm · UV ${Number(days.uv_index_max?.[i]||0).toFixed(0)}<br>Sunrise ${days.sunrise?.[i]?.slice(11,16)||'—'} · sunset ${days.sunset?.[i]?.slice(11,16)||'—'}</small></details></article>`).join('');
 const hourRows=(h.time||[]).map((time,i)=>({time,i})).filter(x=>new Date(x.time).getTime()>=new Date(c.time).getTime()).slice(0,12).map(({time,i})=>`<article class="forecast-hour"><strong>${time.slice(11,16)}</strong><span>${Math.round(h.temperature_2m?.[i]||0)}°C</span><small>Rain ${h.precipitation_probability?.[i]??'—'}% · ${Number(h.precipitation?.[i]||0).toFixed(1)} mm</small><small>Wind ${Math.round(h.wind_speed_10m?.[i]||0)} · gust ${Math.round(h.wind_gusts_10m?.[i]||0)} km/h</small><small>ET₀ ${Number(h.et0_fao_evapotranspiration?.[i]||0).toFixed(1)} mm</small></article>`).join('');
 return title+`<section class="panel forecast-panel"><div class="forecast-heading"><div><span class="pill">LIVE · Open-Meteo</span><h2>${esc(weatherData.place)}</h2><p>Updated ${fmtTime(weatherData.fetchedAt)}</p></div><strong class="forecast-temp">${Math.round(c.temperature_2m)}°</strong><span>${weatherText(c.weather_code)}</span></div><div class="weather-metrics"><div><small>Feels like</small><strong>${Math.round(c.apparent_temperature)}°C</strong></div><div><small>Humidity</small><strong>${Math.round(c.relative_humidity_2m)}%</strong></div><div><small>Rain now</small><strong>${Number(c.precipitation||0).toFixed(1)} mm</strong></div><div><small>Wind and gust</small><strong>${Math.round(c.wind_speed_10m)} / ${Math.round(c.wind_gusts_10m||0)} km/h</strong></div></div></section>${panel('Next 12 hours','ET₀ is a reference value, not measured crop water need.',`<div class="forecast-hour-grid">${hourRows}</div>`)}${panel('Next five days','Expand a day for wind, rain hours, reference ET₀, UV and daylight times.',`<div class="forecast-days">${cards}</div>`)}<section class="panel"><h2>For field planning</h2><p>Nearby grid forecasts may differ from your plot; they do not diagnose crop disease or set irrigation amounts.</p><a class="btn" href="https://agromet.imd.gov.in/index.php/login/adv_status_index" target="_blank" rel="noopener">Check IMD advisories ${icon('arrow',13)}</a><span>Source: Open-Meteo · nearby grid cell, not plot sensors</span>${weatherError?`<p class="notice amber">${esc(weatherError)}</p>`:''}</section>`;
};
resources=function(){const p=plan.best;if(!p)return head('Water & budget','Plan crop water against what you have.',button('Edit farm','edit',false,'settings'))+noPlan();const rows=FW.crops.map((c,i)=>{const area=p.a[i],total=area*c.water,share=state.water?Math.min(100,total/state.water*100):0;if(area<=.001)return'';return'<article class="water-crop"><div class="water-crop-top"><strong><i class="crop-dot" style="background:'+c.color+'"></i>'+c.name+'</strong><span>'+formatArea(area)+'</span></div><div class="water-crop-metrics"><div><small>Example need per hectare</small><strong>'+num(c.water)+' m³</strong></div><div><small>Season total</small><strong>'+num(total)+' m³</strong><small>'+num(total*1000)+' L total</small></div><div><small>Of your water limit</small><strong>'+share.toFixed(0)+'%</strong></div></div><div class="bar water-bar"><span style="width:'+share+'%;background:'+c.color+'"></span></div><details class="plain-details"><summary>Simple planning split</summary><p>Plan watering around early growth, active growth, flowering or fruit formation, and harvest. Fieldwise does not calculate water timing by crop stage. Check local crop guidance and recent rain before irrigating.</p></details></article>'}).join('');return head('Water & budget','See how the crop plan uses your available water.',button('Edit farm','edit',false,'settings'))+'<div class="overview-metrics"><div class="overview-metric"><span>Available</span><strong>'+num(state.water)+' m³</strong></div><div class="overview-metric"><span>Planned</span><strong>'+num(p.water)+' m³</strong></div><div class="overview-metric"><span>Buffer</span><strong>'+num(Math.max(0,state.water-p.water))+' m³</strong></div></div>'+panel('Water by crop','Example seasonal amounts from the planning model. 1 m³ = 1,000 litres.',rows||'<p>No crop mix selected yet.</p>')+'<section class="panel"><h2>Before you irrigate</h2><p>Check soil moisture and recent rain in the field. These estimates use sample crop values; they do not read sensors or measure actual water. Effective rainfall and irrigation efficiency are not included.</p></section>'};
finance=function(){const p=plan.best,due=bills.reduce((n,b)=>n+Math.max(0,Number(b.amount||0)-(b.payments||[]).reduce((x,y)=>x+Number(y.amount||0),0)),0),paid=bills.reduce((n,b)=>n+(b.payments||[]).reduce((x,y)=>x+Number(y.amount||0),0),0),rows=bills.map(b=>{const pb=(b.payments||[]).reduce((n,x)=>n+Number(x.amount||0),0),left=Math.max(0,Number(b.amount)-pb);return'<article class="simple-bill"><div><strong>'+esc(b.supplier||'Farm bill')+'</strong><small>'+esc(b.category||'Farm cost')+' · '+(b.dueDate||'No due date')+'</small></div><strong>'+money(left)+' <small>'+(left?'due':'paid')+'</small></strong>'+(left?'<button class="btn" data-pay="'+esc(b.id)+'">Record payment</button>':'<span class="pill">Paid</span>')+'</article>'}).join(''),payments=bills.flatMap(b=>(b.payments||[]).map(x=>({...x,supplier:b.supplier}))).sort((a,b)=>(b.date||'').localeCompare(a.date||''));return head('Money & bills','Season budget and farm bills together.',button('Export bills','billing-export',false,'down')+button('Add bill','billing-add',true,'plus'))+'<div class="overview-metrics"><div class="overview-metric"><span>Budget left after plan</span><strong>'+money(Math.max(0,state.budget-(p?.cost||0)))+'</strong></div><div class="overview-metric"><span>Bills still due</span><strong>'+money(due)+'</strong></div><div class="overview-metric"><span>Paid and recorded</span><strong>'+money(paid)+'</strong></div></div><section class="panel"><h2>Season estimate</h2><div class="metric-list"><div><span>Budget entered</span><strong>'+money(state.budget)+'</strong></div><div><span>Planned crop costs</span><strong>'+money(p?.cost||0)+'</strong></div><div><span>Possible net return</span><strong>'+(p?money(p.mean):'—')+'</strong></div></div><p class="tiny">Return uses example crop prices and yields. Check local costs before spending.</p></section>'+localEconomicsPanel()+panel('Farm bills',bills.length+' recorded',rows||'<div class="empty"><p>No bills yet.</p><button class="btn primary" data-act="billing-add">Add your first bill</button></div>')+(payments.length?'<details class="panel plain-details"><summary>Recent payments ('+payments.length+')</summary>'+payments.slice(0,8).map(x=>'<div class="simple-bill"><span>'+esc(x.supplier)+' · '+(x.date||'—')+'</span><strong>'+money(x.amount)+'</strong></div>').join('')+'</details>':'')+'<p class="notice">Bills are records only. Pay using your usual method, then record it here; Fieldwise does not move money.</p>'};
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b)return;if(b.dataset.act==='weather-load'||b.dataset.act==='weather-refresh'){loadWeather();return}});
document.addEventListener('submit',e=>{if(e.target?.id==='profile-form'){e.preventDefault();const fd=new FormData(e.target);state={...state,farmerName:String(fd.get('farmerName')||'').trim(),primaryCrop:String(fd.get('primaryCrop')||''),region:String(fd.get('region')||'').trim(),profileComplete:true};plan=FW.optimize(state);persist('fw-context',state);render();toast('Farmer profile saved.');return}});
document.addEventListener('submit',e=>{if(e.target?.id!=='economics-form')return;e.preventDefault();const fd=new FormData(e.target),next={...(state.cropEconomics||{})};for(let i=0;i<FW.crops.length;i++){const c=FW.crops[i],pricePerQ=Number(fd.get(`price-${i}`)),costPerHa=Number(fd.get(`cost-${i}`));if(!(pricePerQ>0&&costPerHa>0)){toast('Enter positive prices and costs for every crop.');return}next[c.name]={pricePerQ,costPerHa}}state={...state,cropEconomics:next,economicsSource:String(fd.get('source')),economicsDate:String(fd.get('date'))};plan=FW.optimize(state);persist('fw-context',state);render();toast('Dated local crop inputs saved. Plans recalculated.')});
document.addEventListener('input',e=>{const key=e.target?.dataset?.stress;if(!key)return;stressControls[key]=Number(e.target.value);const output=$(`#stress-${key}-out`);if(output)output.textContent=stressControls[key]+'%';const result=FW.optimize({...state,rain:Number(state.rain||0)-stressControls.rain,price:Number(state.price||0)-stressControls.price,costShock:stressControls.cost,water:state.water*stressControls.water/100});const target=$('#custom-stress-result');if(target)target.innerHTML=customStressResult(result)});
